# GDU cards: UI FRAMEWORK + TV + CHANNELS of the Godot rebuild (docs/GODOT.md). Theme, widgets, HUD, main scene, the big CRT TV
# with remote and channel manager, and the five channels (SHOP, NEWS, ADVERTS, LEDGER, BOOKINGS). No game rules live here:
# channels read `game.state` / `Data` and act only through `game.act(...)`.
MODE = "godot"

# Card ids of the foundation set (GDF.py). Change them HERE if the numbering changes.
SKEL, HARN, DATA, FMT, GAME, SFX, TOK = "GDF01", "GDF02", "GDF03", "GDF07", "GDF10", "GDF12", "GDF13"

PLAN = "docs/GODOT.md (the plan: layout zones, the TV is the centre, tap rule, 64 px touch targets)"
TESTS = ("godot/tests/harness.gd (GDF02): a test file starts with `extends \"res://tests/harness.gd\"` (it is a RefCounted, so there is NO scene and NO `await`); "
         "every `func test_*() -> void` runs; helpers `ok(cond, msg)`, `eq(a, b, msg)`, `near(a, b, eps, msg)`, `tree()` (the SceneTree), `autoload(name)`. "
         "To test a node: `tree().root.add_child(n)` and finish the test with `n.free()`. Never wait for frames: every animated widget has `advance(dt)` "
         "(seconds) so a test steps time by hand. Mouse input is simulated by calling the widget's public `handle_event(ev)`; copy this helper into the test file: "
         "`func _mb(pos: Vector2, down: bool) -> InputEventMouseButton:` creating `InputEventMouseButton.new()` with `button_index = MOUSE_BUTTON_LEFT`, `pressed = down`, `position = pos`")
THEME = "godot/ui/ui_theme.gd (GDU01: `UiTheme.color(name)`, `font_for(role)`, `size_for(role)`, `draw_box`, `draw_text`, `draw_bar`, `TOUCH`)"
TAPR = "godot/ui/tap.gd (GDU02: `UiTap` with `press(id)`, `release(id) -> bool`, `cancel()`)"
BTN = "godot/ui/button.gd (GDU02: `UiButton`: `text`, `kind`, `enabled`, signals `activated` and `blocked`, `handle_event(ev)`, `activate()`)"
UTXT = "godot/ui/ui_text.gd (GDU31: `UiText.wrap(text, max_chars, max_lines) -> Array[String]`, `ellipsize(text, max_chars)`, `pips(n)`)"
CB = "godot/tv/channel_base.gd (GDU12: `ChannelBase`, the channel contract, `_paint()`, `refresh()`, `toast()`, `model_of()`, `paint_of()`)"
FAKE = "godot/tests/fake_game.gd (GDU28: `TestFakeGame`, a stand-in for Game with `state`, `act()`, `acts`, `toasts`, `next_result`, signals `changed`, `toast_requested`)"
LSTW = "godot/ui/list.gd (GDU18: `UiList`)"
CHAN = ("Channel screens are 640x448 (the SubViewport inside the TV) and are shown at 600x420 on the glass (scale 0.9375), so every interactive control "
        "inside a channel is at least 72x72 channel px (72 * 0.9375 = 67.5 stage px, above the 64 px rule).")
SHOT = ("Screenshot step: run `sh tools/godot/gshot.sh tests/shots/{n}_shot.tscn /tmp/{n}.png 8`, then LOOK at /tmp/{n}.png with the Read tool and describe in your "
        "final reply what you see (is the text readable, does anything overlap or run off the 640x448 screen, are the buttons visible). Fix what is wrong.")
SHOT_SCENE = ("`godot/tests/shots/{n}_shot.tscn` (text scene, exactly: `[gd_scene load_steps=2 format=3]`, blank line, "
              "`[ext_resource type=\"Script\" path=\"res://tests/shots/channel_shot.gd\" id=\"1\"]`, blank line, `[node name=\"Shot\" type=\"Control\"]`, then the lines "
              "`layout_mode = 3`, `anchors_preset = 15`, `anchor_right = 1.0`, `anchor_bottom = 1.0`, `script = ExtResource(\"1\")`, "
              "`metadata/channel = \"res://tv/{n}_channel.tscn\"`)")
CH_TSCN = ("`godot/tv/{n}_channel.tscn` (text scene, exactly: `[gd_scene load_steps=2 format=3]`, blank line, "
           "`[ext_resource type=\"Script\" path=\"res://tv/{n}_channel.gd\" id=\"1\"]`, blank line, `[node name=\"{N}Channel\" type=\"Control\"]`, then `script = ExtResource(\"1\")`)")
ASCII = "Player-visible strings are ASCII; any pound sign comes from `CoreFormat.money()` only (never type the pound character)."


def shot(n):
    return SHOT.format(n=n)


def shot_scene(n):
    return SHOT_SCENE.format(n=n)


def ch_tscn(n):
    return CH_TSCN.format(n=n, N=n.capitalize())


CARDS = [

 # ------------------------------------------------------------------------------------------------ theme, text, button
 dict(id="GDU01", title="UI: UiTheme, theme.tres and bundled pixel fonts", needs=[SKEL, TOK],
  files=["godot/ui/fonts/PressStart2P-Regular.ttf", "godot/ui/fonts/VT323-Regular.ttf", "godot/ui/fonts/OFL-PressStart2P.txt", "godot/ui/fonts/OFL-VT323.txt",
         "godot/ui/ui_theme.gd", "godot/ui/theme.tres", "godot/tests/test_ui_theme.gd"],
  goal="The shared look: the two pixel fonts imported into the project, `UiTheme` (font roles, drawing helpers all widgets use) and `godot/ui/theme.tres` for stock Controls. Colours are NOT redefined: `UiTheme.color()` just asks `UiTokens` (GDF13).",
  read=[PLAN, TESTS, "godot/ui/tokens.gd (GDF13: `UiTokens.col(key)`, `FLOOR`, `COLOR`, `PALETTE`)", "src/ui/theme.js (font sizes) and src/ui/kit_draw.js `panel` (the boxed look: 4 px ink border, drop shadow)"],
  steps=[
   "Copy the fonts: `mkdir -p godot/ui/fonts && cp assets/fonts/PressStart2P-Regular.ttf assets/fonts/VT323-Regular.ttf assets/fonts/OFL-PressStart2P.txt assets/fonts/OFL-VT323.txt godot/ui/fonts/`.",
   r'''`godot/ui/ui_theme.gd`: `class_name UiTheme`, `extends RefCounted`, all static and typed. `const TOUCH := 64` (smallest touch target in stage px) and `const GRID := 4`. `const FONT_TITLE_PATH := "res://ui/fonts/PressStart2P-Regular.ttf"`, `const FONT_BODY_PATH := "res://ui/fonts/VT323-Regular.ttf"`. `const ROLES: Dictionary = {"number": ["title", 48], "h1": ["title", 32], "h2": ["title", 24], "h3": ["title", 16], "button": ["title", 16], "hero": ["body", 40], "body": ["body", 28], "caption": ["body", 24]}` (role -> [font kind, px]).''',
   r'''Fonts: `static var _fonts: Dictionary = {}`. `static func _load(path: String) -> Font`: return the cached one, else `var f := load(path) as FontFile`; if it is not null set `f.antialiasing = TextServer.FONT_ANTIALIASING_NONE`, `f.hinting = TextServer.HINTING_NONE`, `f.subpixel_positioning = TextServer.SUBPIXEL_POSITIONING_DISABLED` (crisp pixel look); cache and return (a missing file gives `ThemeDB.fallback_font`). `static func title_font() -> Font` and `static func body_font() -> Font` call `_load` with the two paths. `static func font_for(role: String) -> Font`: `title_font()` when the role's kind is "title" else `body_font()`; an unknown role uses "body". `static func size_for(role: String) -> int` returns the px (unknown role: 28). `static func color(key: String) -> Color` returns `UiTokens.col(key)`.''',
   r'''Drawing helpers (call them only from inside a `_draw()`): `static func draw_box(item: CanvasItem, rect: Rect2, fill: Color, border: Color = Color(0.0784, 0.0627, 0.1647, 1.0), bw: int = 4, shadow: bool = true) -> void`: when `shadow`, `item.draw_rect(Rect2(rect.position + Vector2(4, 4), rect.size), Color(0, 0, 0, 0.35))`; then `item.draw_rect(rect, border)` filled; then `item.draw_rect(rect.grow(-bw), fill)` filled (so the border is `bw` px thick INSIDE the rect). `static func draw_text(item: CanvasItem, text: String, pos: Vector2, role: String, col: Color, width: float = -1.0, align: int = HORIZONTAL_ALIGNMENT_LEFT) -> void`: `pos` is the TOP-LEFT of the line; `var f := font_for(role); var s := size_for(role); item.draw_string(f, pos + Vector2(0, f.get_ascent(s)), text, align, width, s, col)`. `static func draw_bar(item: CanvasItem, rect: Rect2, ratio: float, fill: Color, back: Color = Color(0.0784, 0.0627, 0.1647, 1.0)) -> void`: draw `rect` filled with `back`, then a filled rect of `fill` at `rect.position + Vector2(2, 2)` with size `Vector2(bar_fill_width(rect, ratio), rect.size.y - 4)`. `static func bar_fill_width(rect: Rect2, ratio: float) -> float`: `(rect.size.x - 4.0) * clampf(ratio, 0.0, 1.0)`.''',
   r'''`godot/ui/theme.tres`: a hand-written text resource `[gd_resource type="Theme" load_steps=7 format=3]`. `[ext_resource type="FontFile" path="res://ui/fonts/VT323-Regular.ttf" id="1"]` and the same for `PressStart2P-Regular.ttf` with id="2". Sub-resources of type StyleBoxFlat: id "1" (normal: bg_color = Color(1, 0.968, 0.863, 1), border_width_left/top/right/bottom = 4, border_color = Color(0.0784, 0.0627, 0.1647, 1), content_margin_left/right = 12, content_margin_top/bottom = 8), id "2" (hover: same but bg_color = Color(1, 0.824, 0.478, 1)), id "3" (pressed: same but bg_color = Color(0.851, 0.796, 0.627, 1)), id "4" (disabled: same but bg_color = Color(0.584, 0.584, 0.584, 1)), id "5" (panel: same as normal). Then `[resource]` with `default_font = ExtResource("1")`, `default_font_size = 28`, `Button/fonts/font = ExtResource("2")`, `Button/font_sizes/font_size = 16`, `Button/colors/font_color = Color(0.0784, 0.0627, 0.1647, 1)`, `Button/styles/normal = SubResource("1")`, `Button/styles/hover = SubResource("2")`, `Button/styles/pressed = SubResource("3")`, `Button/styles/disabled = SubResource("4")`, `Label/colors/font_color = Color(0.0784, 0.0627, 0.1647, 1)`, `PanelContainer/styles/panel = SubResource("5")`.''',
   r'''`godot/tests/test_ui_theme.gd`: `test_colors` (`UiTheme.color("ink") == UiTokens.col("ink")`; `UiTheme.color("gold") == Color("#E8B923")`; an unknown key returns `Color.MAGENTA`); `test_roles` (`size_for("h1") == 32`, `size_for("number") == 48`, `size_for("body") == 28`, `size_for("caption") == 24`, unknown role 28; loop over `UiTheme.ROLES`: kind "title" roles have px >= `UiTokens.FLOOR.title`, kind "body" roles have px >= `UiTokens.FLOOR.body`); `test_fonts` (`font_for("h1") != null`, `title_font() != body_font()`, `font_for("zzz") == body_font()`, and `title_font().antialiasing == TextServer.FONT_ANTIALIASING_NONE` when it is a FontFile); `test_bar_fill_width` (`bar_fill_width(Rect2(0, 0, 104, 10), 0.5)` near 50.0; ratio 2.0 gives 100.0; ratio -1.0 gives 0.0); `test_touch` (`UiTheme.TOUCH == 64`); `test_theme_resource` (`var t := load("res://ui/theme.tres") as Theme`; not null; `t.default_font != null`; `t.default_font_size == 28`; `t.get_stylebox("normal", "Button") != null`).'''],
  accept=["`sh tools/godot/gtest.sh test_ui_theme` last line is `GDTEST OK` (the run also imports the fonts on CASE)."],
  oos=["godot/ui/tokens.gd (GDF13), project.godot (do not set a project-wide theme here)."]),

 dict(id="GDU31", title="UI: UiText wrap, ellipsize, pips", needs=[SKEL, HARN],
  files=["godot/ui/ui_text.gd", "godot/tests/test_ui_text.gd"],
  goal="Pure text helpers shared by banner, toasts and channels. Wrapping works on CHARACTER COUNTS (the game fonts are monospaced) so it is testable headless.",
  read=[PLAN, TESTS],
  steps=[
   r'''`godot/ui/ui_text.gd`: `class_name UiText`, `extends RefCounted`, static, typed. `static func wrap(text: String, max_chars: int, max_lines: int = 0) -> Array[String]`: split `text` on single spaces (`text.split(" ", false)`; a `\n` inside the text is replaced by a space first). Greedy: `cur = ""`; for each word: if `cur == ""` then `cur = word` (a word longer than `max_chars` keeps its own line, never broken); elif `cur.length() + 1 + word.length() <= max_chars` then `cur += " " + word`; else push `cur` and `cur = word`. After the loop push `cur` if it is not empty. If `max_lines > 0` and there are more lines than `max_lines`: drop the extra lines and replace the last kept line `L` by `L.substr(0, max_chars - 3) + "..."` when `L.length() + 3 > max_chars`, else `L + "..."` (an overflow always ends with three dots, and the last line is never longer than `max_chars` unless it is a single long word).''',
   r'''`static func ellipsize(text: String, max_chars: int) -> String`: return `text` when `text.length() <= max_chars`; when `max_chars <= 3` return `text.substr(0, max_chars)`; else `text.substr(0, max_chars - 3) + "..."`. `static func pips(n: int, total: int = 10) -> String`: `n` clamped to 0..total; `"*".repeat(n) + "-".repeat(total - n)` (ASCII stand-in for stars). `static func upper(text: String) -> String`: `text.to_upper()`. `static func lines_height(count: int, pitch: int) -> int`: `count * pitch`.''',
   r'''`godot/tests/test_ui_text.gd`: `test_wrap_basic`: `UiText.wrap("ONE TWO THREE FOUR", 9, 3)` equals `["ONE TWO", "THREE", "FOUR"]`; `wrap("", 10, 3)` equals `[]`; `wrap("HELLO", 3, 3)` equals `["HELLO"]` (long word kept); `wrap("AAAA BBBB CCCC DDDD", 4, 3)` equals `["AAAA", "BBBB", "C..."]`; `wrap("AA BB CC", 5, 0)` equals `["AA BB", "CC"]`; `wrap("A B C D", 3, 2)` equals `["A B", "C D"]` (exactly two lines, no overflow, no dots). `test_ellipsize`: `ellipsize("HELLO WORLD", 8) == "HELLO..."`, `ellipsize("HELLO", 8) == "HELLO"`, `ellipsize("HELLO", 3) == "HEL"`, `ellipsize("HELLO", 5) == "HELLO"`. `test_pips`: `pips(3) == "***-------"`, `pips(0) == "----------"`, `pips(12) == "**********"`, `pips(-1) == "----------"`, `pips(2, 4) == "**--"`. `test_upper_height`: `upper("ab") == "AB"`, `lines_height(3, 30) == 90`.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_text` last line is `GDTEST OK`."]),

 dict(id="GDU02", title="UI: UiTap rule and UiButton widget", needs=["GDU01", HARN],
  files=["godot/ui/tap.gd", "godot/ui/button.gd", "godot/tests/test_ui_button.gd"],
  goal="The tap rule as a tiny class every widget reuses (remember the pressed control on press, activate on release over the SAME control), and the stock button widget (64x64 minimum).",
  read=[PLAN, TESTS, THEME, "src/ui/kit_hits.js (the JS tap rule: pressed id remembered on down, compared on up) and src/ui/kit_draw.js `button`"],
  steps=[
   r'''`godot/ui/tap.gd`: `class_name UiTap`, `extends RefCounted`. `var pressed_id: String = ""`. `func press(id: String) -> void: pressed_id = id`. `func release(id: String) -> bool`: `var hit := pressed_id != "" and id == pressed_id`; set `pressed_id = ""`; return `hit`. `func cancel() -> void` clears it. `func is_down() -> bool: return pressed_id != ""`.''',
   r'''`godot/ui/button.gd`: `class_name UiButton`, `extends Control`. Signals `activated` and `blocked` (a tap on a disabled button). Vars with setters that call `queue_redraw()`: `text: String`, `kind: String = "normal"` (one of "normal", "primary", "remote", "card"), `enabled: bool = true`, `hot: bool = false` (highlighted/selected), `role: String = "button"`. `var down: bool = false`, `var _tap := UiTap.new()`. `_init()`: `custom_minimum_size = Vector2(64, 64)`, `size = Vector2(64, 64)`, `mouse_filter = Control.MOUSE_FILTER_STOP`, `focus_mode = Control.FOCUS_NONE`.''',
   r'''Input: `func _gui_input(event: InputEvent) -> void: handle_event(event)`. `func handle_event(ev: InputEvent) -> void`: only `InputEventMouseButton` with `button_index == MOUSE_BUTTON_LEFT` matters. On press: `_tap.press("b")`, `down = true`, `queue_redraw()`. On release: `var inside := Rect2(Vector2.ZERO, size).has_point(ev.position)`; `var hit := _tap.release("b" if inside else "")`; `down = false`; `queue_redraw()`; if `hit` then `activate()`. `func activate() -> void`: `if enabled: activated.emit() else: blocked.emit()` (the keyboard OK path uses it too). A release without a press does nothing (UiTap returns false).''',
   r'''`_draw()`: colours by `kind` (use `UiTheme.color(...)`): normal = fill "paper", text "ink"; primary = fill "good", text "white"; remote = fill "darkgrey", border "black", text "cream"; card = fill "cream", text "ink". A disabled button (`enabled == false`) uses fill "lightgrey" and text "midgrey". While `down` the fill is `fill.darkened(0.15)` and the text is drawn 2 px lower. Draw with `UiTheme.draw_box(self, Rect2(Vector2.ZERO, size), fill, border, 4, not down)`. When `hot` also draw a 4 px "lamp" outline just inside the border (four thin filled rects). The text may contain `\n` (at most 2 lines): split on `\n`, pitch = `UiTheme.size_for(role) + 4`, the block is centred vertically in `size.y`, each line is centred horizontally with `UiTheme.draw_text(self, line, Vector2(0, y), role, text_col, size.x, HORIZONTAL_ALIGNMENT_CENTER)`.''',
   r'''`godot/tests/test_ui_button.gd`: `test_tap_class`: `var t := UiTap.new()`; `t.press("a")`; `t.release("a")` true; `t.release("a")` false (second release); `t.press("a")`, `t.release("b")` false and `t.is_down()` false; `t.press("")`, `t.release("")` false; `t.press("a")`, `t.cancel()`, `t.release("a")` false. `test_button_min_size`: a new UiButton has `custom_minimum_size` equal to `Vector2(64, 64)`. `test_button_tap`: button with `size = Vector2(200, 64)` and an Array `hits`; connect `activated` to `func(): hits.append(1)`; press at (10, 10) and release at (12, 12) gives 1 hit; press inside and release at (500, 10) (outside) gives still 1 hit (no new); a release with no press gives still 1; press inside + release inside again gives 2. `test_button_disabled`: `enabled = false`; connect `blocked` to count; press+release inside: `activated` count 0 and `blocked` count 1. `test_button_activate`: `activate()` emits `activated` once when enabled. `test_down_state`: after a press `down` is true, after the release it is false.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_button` last line is `GDTEST OK`."]),

 dict(id="GDU03", title="UI: pop-up menu widget (boxed list with arrow cursor)", needs=["GDU02", "GDU01"],
  files=["godot/ui/menu.gd", "godot/tests/test_ui_menu.gd"],
  goal="The Rock-Star-Ate-My-Hamster style pop-up menu: a small boxed list with a blinking arrow cursor beside the selected row. Used beside the TV and in rooms; rows are 64 px tall.",
  read=[PLAN, TESTS, THEME, TAPR, "docs/art/RSAMH_STYLE.md section 4 (in-scene pop-up menu)"],
  steps=[
   r'''`godot/ui/menu.gd`: `class_name UiMenu`, `extends Control`. Signals `chosen(index: int)` and `cancelled`. Consts `ROW := 64`, `PAD := 8`, `CHAR_W := 12`. Vars `items: Array[String] = []`, `disabled: Dictionary = {}` (row index -> true), `selected: int = 0`, `var _t: float = 0.0`, `var _tap := UiTap.new()`. `visible = false` in `_init`, `mouse_filter = MOUSE_FILTER_STOP`.''',
   r'''`static func width_for(list: Array) -> int`: `maxi(280, 44 + CHAR_W * longest + 24)` where `longest` is the length of the longest item (0 for an empty list). `func open(list: Array[String], at: Vector2 = Vector2.ZERO) -> void`: `items = list`, `disabled = {}`, `position = at`, `size = Vector2(width_for(list), ROW * list.size() + 2 * PAD)`, `selected = first_enabled()`, `_t = 0.0`, `visible = true`, `queue_redraw()`. `func close() -> void: visible = false`. `func set_item_enabled(i: int, on: bool) -> void` (updates `disabled`). `func first_enabled() -> int`: the first non-disabled index, or 0. `func row_rect(i: int) -> Rect2`: `Rect2(PAD, PAD + i * ROW, size.x - 2 * PAD, ROW)`. `func row_at(pos: Vector2) -> int`: the row whose `row_rect` contains `pos`, else -1.''',
   r'''Keys and choosing: `func move(delta: int) -> void`: step `selected` by `delta` (+1 or -1), wrapping with `posmod`, skipping disabled rows (at most `items.size()` attempts; if all are disabled nothing changes). `func choose() -> void`: if the list is empty or the selected row is disabled do nothing; else `var i := selected`, `close()`, `chosen.emit(i)`. `func cancel() -> void: close(); cancelled.emit()`. `func advance(dt: float) -> void: _t += dt; queue_redraw()`; `_process(dt)` calls `advance(dt)` while visible. `func blink_on() -> bool: return int(_t * 4.0) % 2 == 0` (2 blinks per second).''',
   r'''`func _gui_input(event: InputEvent) -> void: handle_event(event)`. `func handle_event(ev: InputEvent) -> void`: left-button press: `var r := row_at(ev.position)`; `_tap.press("row%d" % r if r >= 0 else "")`; if `r >= 0` and it is not disabled set `selected = r`; `queue_redraw()`. Left-button release: `var r := row_at(ev.position)`; if `_tap.release("row%d" % r if r >= 0 else "")` and not disabled(r) then `selected = r; choose()`. `InputEventKey` pressed: KEY_UP -> `move(-1)`, KEY_DOWN -> `move(1)`, KEY_ENTER / KEY_KP_ENTER / KEY_SPACE -> `choose()`, KEY_ESCAPE -> `cancel()`.''',
   r'''`_draw()`: `UiTheme.draw_box(self, Rect2(Vector2.ZERO, size), UiTheme.color("paper"), UiTheme.color("ink"), 4, true)`. For each row i: if `i == selected` fill `row_rect(i)` with "lamp" at alpha 0.35; text at `row_rect(i).position + Vector2(36, 18)` with role "body", colour "ink" (colour "lightgrey" for disabled rows). The arrow cursor (only when `blink_on()` and the selected row is enabled): `draw_colored_polygon(PackedVector2Array([Vector2(12, cy - 10), Vector2(12, cy + 10), Vector2(30, cy)]), UiTheme.color("ink"))` where `cy = row_rect(selected).get_center().y`.''',
   r'''`godot/tests/test_ui_menu.gd`: `test_width_size`: `UiMenu.width_for(["A", "BB"]) == 280`; an item of 30 characters gives `44 + 12 * 30 + 24 == 428`; after `open(["A","B","C"] as Array[String], Vector2(5, 6))`: `position == Vector2(5, 6)`, `size == Vector2(280, 208)` (3 * 64 + 16), `visible`, `selected == 0`. `test_rows`: `row_rect(1) == Rect2(8, 72, 264, 64)`; `row_at(Vector2(20, 80)) == 1`; `row_at(Vector2(2, 80)) == -1`; `row_at(Vector2(20, 300)) == -1`. `test_move`: `move(1)` gives 1; `move(-1)` twice gives 2 (wraps); with `set_item_enabled(1, false)` from 0 `move(1)` gives 2. `test_choose_and_cancel`: connect `chosen` to push the index into an Array: `selected = 2; choose()` gives `[2]` and `visible == false`; reopen, `cancel()` emits `cancelled` once; a choose on a disabled row emits nothing. `test_tap`: reopen; press at (20, 80) (row 1), release at (20, 85): `chosen` gets 1; reopen; press on row 1 and release on row 2 (20, 150): nothing chosen; press outside rows (2, 80) and release there: nothing. `test_blink`: `advance(0.0)` gives `blink_on()` true; `advance(0.25)` false; `advance(0.25)` true.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_menu` last line is `GDTEST OK`."]),

 dict(id="GDU04", title="UI: toast and tooltip widgets", needs=["GDU01", "GDU31"],
  files=["godot/ui/toast.gd", "godot/ui/tooltip.gd", "godot/tests/test_ui_toast.gd"],
  goal="Two pop-up Controls: `UiToast` (stacked slide-in messages, max 3 at once, rest queued) and `UiTooltip` (small label that appears after a short delay next to a rectangle, clamped on screen).",
  read=[PLAN, TESTS, THEME, UTXT, "src/ui/overlays.js (toast look and timings: in 0.26 s, hold 2.5 s, out 0.2 s)"],
  steps=[
   r'''`godot/ui/toast.gd`: `class_name UiToast`, `extends Control`. Consts `IN := 0.26`, `OUT := 0.2`, `MAX_VISIBLE := 3`, `MAX_QUEUE := 8`, `MAX_CHARS := 60`, `ROW_H := 48`, `GAP := 8`. `mouse_filter = MOUSE_FILTER_IGNORE` (set in `_init`). Vars `items: Array = []` (each a Dictionary `{"text": String, "age": float, "hold": float}`), `queue: Array = []` (pending Dictionaries).''',
   r'''`func show_text(text: String, hold: float = 2.5) -> void`: `var t := UiText.ellipsize(text, MAX_CHARS)`; if `t == ""` return; if `items` is not empty and `items.back().text == t` then `items.back().age = 0.0` and return; if `items.size() >= MAX_VISIBLE`: append to `queue` (if the queue already has `MAX_QUEUE` entries drop the oldest first) else append the item to `items`. `queue_redraw()`. `func advance(dt: float) -> void`: add `dt` to every item's age; remove items whose age > `IN + hold + OUT`; then while `items.size() < MAX_VISIBLE` and the queue is not empty move `queue.pop_front()` into `items`; `queue_redraw()`. `_process(dt)` calls `advance(dt)`. `func alpha_of(item: Dictionary) -> float`: `age < IN` -> `age / IN`; `age < IN + hold` -> 1.0; else `clampf(1.0 - (age - IN - item.hold) / OUT, 0.0, 1.0)`. `func active_count() -> int`, `func queued_count() -> int`, `func texts() -> Array[String]` (texts of `items`, oldest first).''',
   r'''`UiToast._draw()`: the newest toast is lowest. For item index i (0 = oldest) the box is `Rect2(x, y, w, ROW_H)` with `w = minf(size.x - 64.0, 12.0 * text.length() + 48.0)`, `x = (size.x - w) / 2.0`, `y = size.y - 140.0 - (items.size() - i) * (ROW_H + GAP) + (1.0 - alpha) * 16.0`. Draw with `UiTheme.draw_box(...)` fill "paper", then the text (role "caption", colour "ink", centred in the box); multiply every colour's alpha by `alpha_of(item)` (build the colours with `Color(c.r, c.g, c.b, c.a * alpha)`).''',
   r'''`godot/ui/tooltip.gd`: `class_name UiTooltip`, `extends Control`. `mouse_filter = MOUSE_FILTER_IGNORE`, starts `visible = false`. Consts `DELAY := 0.4`, `MARGIN := 8`. Vars `text: String`, `_pending: bool`, `_wait: float`, `_anchor: Rect2`, `bounds: Vector2 = Vector2(1280, 720)`. `static func measure(text: String) -> Vector2`: `Vector2(10.0 * text.length() + 24.0, 40.0)`. `static func compute_position(anchor: Rect2, tip: Vector2, limit: Vector2) -> Vector2`: `x = anchor.get_center().x - tip.x / 2.0`, `y = anchor.position.y - tip.y - 8.0`; if `y < 0.0` then `y = anchor.end.y + 8.0`; clamp `x` to `[0.0, maxf(0.0, limit.x - tip.x)]` and `y` to `[0.0, maxf(0.0, limit.y - tip.y)]`; return `Vector2(x, y)`.''',
   r'''`func request(tip_text: String, anchor: Rect2) -> void`: store text/anchor, `_pending = true`, `_wait = 0.0`, `visible = false`. `func advance(dt: float) -> void`: if `_pending`, `_wait += dt`; when `_wait >= DELAY`: `_pending = false`, `size = measure(text)`, `position = compute_position(_anchor, size, bounds)`, `visible = true`, `queue_redraw()`. `func hide_tip() -> void`: `_pending = false; visible = false`. `_process(dt)` calls `advance(dt)`. `_draw()`: `UiTheme.draw_box(self, Rect2(Vector2.ZERO, size), UiTheme.color("night"), UiTheme.color("lamp"), 2, true)` and the text (role "caption", colour "cream") at (12, 8).''',
   r'''`godot/tests/test_ui_toast.gd`: `test_toast_flow`: new UiToast `t` with `size = Vector2(1280, 720)`; `show_text("A")` -> `active_count() == 1`; `advance(1.0)` still 1; `advance(2.5)` (total 3.5, past 0.26 + 2.5 + 0.2 = 2.96) -> 0. `test_toast_limits`: show "A", "B", "C", "D": `active_count() == 3`, `queued_count() == 1`, `texts() == ["A", "B", "C"]`; `advance(3.5)` removes the first three and promotes D in the same call: `texts() == ["D"]`, `queued_count() == 0`. `test_toast_duplicate`: `show_text("A")`, `advance(0.5)`, `show_text("A")`: still 1 item and its `age` is 0.0. `test_toast_truncate`: a 100-character string is stored as 60 characters ending in "...". `test_toast_alpha`: `alpha_of({"text": "x", "age": 0.13, "hold": 2.5})` near 0.5 (eps 0.001); age 1.0 -> 1.0; age `0.26 + 2.5 + 0.1` -> near 0.5. `test_tooltip_position`: `UiTooltip.compute_position(Rect2(100, 100, 40, 40), Vector2(80, 40), Vector2(1280, 720)) == Vector2(80, 52)`; an anchor at `Rect2(100, 10, 40, 40)` (no room above) gives y == 58; an anchor at `Rect2(1270, 300, 40, 40)` gives x == 1200 (clamped: 1280 - 80). `test_tooltip_delay`: `request("HELLO", Rect2(100, 100, 40, 40))`; `advance(0.3)` -> not visible; `advance(0.2)` -> visible and `size == UiTooltip.measure("HELLO")`; `hide_tip()` -> not visible; `request` then `hide_tip()` then `advance(1.0)` stays hidden. `UiTooltip.measure("HELLO") == Vector2(74, 40)`.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_toast` last line is `GDTEST OK`."]),

 dict(id="GDU05", title="UI: animated money and number counter", needs=["GDU01", FMT],
  files=["godot/ui/counter.gd", "godot/tests/test_ui_counter.gd"],
  goal="`UiCounter`: a number that rolls up or down to its new value over 0.7 s (ease-out cubic) and flashes green when it rises and red when it falls. Used by the CASH bar and anywhere else money changes.",
  read=[PLAN, TESTS, THEME, "godot/core/format.gd (GDF07: `CoreFormat.money(n)`)", "src/ui/tokens.js EASE.outCubic and MOTION.count (700 ms)"],
  steps=[
   r'''`godot/ui/counter.gd`: `class_name UiCounter`, `extends Control`. Consts `DURATION := 0.7`. Vars with setters calling `queue_redraw()`: `money_mode: bool = true`, `prefix: String = ""`, `suffix: String = ""`, `role: String = "h2"`, `align: int = HORIZONTAL_ALIGNMENT_LEFT`, `base_color: Color = UiTheme.color("white")`. Private: `_from: float`, `_to: float`, `_shown: float`, `_elapsed: float = DURATION` (finished), `_dir: int = 0` (1 rising, -1 falling, 0 none). `mouse_filter = MOUSE_FILTER_IGNORE` in `_init`; `size = Vector2(240, 48)`.''',
   r'''`func set_value(v: float, animate: bool = true) -> void`: if `not animate` or `v == _shown`: `_from = v; _to = v; _shown = v; _elapsed = DURATION; _dir = 0`. Else: `_from = _shown; _to = v; _elapsed = 0.0; _dir = 1 if v > _shown else -1`. `queue_redraw()`. `func advance(dt: float) -> void`: if `_elapsed >= DURATION` return; `_elapsed = minf(DURATION, _elapsed + dt)`; `var u := _elapsed / DURATION`; `var e := 1.0 - pow(1.0 - u, 3.0)`; `_shown = _from + (_to - _from) * e`; when `_elapsed >= DURATION`: `_shown = _to; _dir = 0`. `queue_redraw()`. `_process(dt)` calls `advance(dt)`. `func value_shown() -> float`, `func target() -> float`, `func is_animating() -> bool: return _elapsed < DURATION`.''',
   r'''`func text() -> String`: `var n := int(floor(_shown + 0.5))`; money mode: `prefix + CoreFormat.money(n) + suffix`; otherwise `prefix + str(n) + suffix`. `func current_color() -> Color`: `_dir == 1` -> `UiTheme.color("good")`, `_dir == -1` -> `UiTheme.color("bad")`, else `base_color`. `_draw()`: `UiTheme.draw_text(self, text(), Vector2(0, (size.y - UiTheme.size_for(role)) / 2.0), role, current_color(), size.x, align)`.''',
   r'''`godot/tests/test_ui_counter.gd` (every `near` in this file uses eps 0.01): `test_instant`: `set_value(1000.0, false)`; `value_shown()` near 1000.0; `text() == CoreFormat.money(1000)`; `is_animating()` false. `test_roll_up`: new counter `c` (money_mode true), `set_value(0.0, false)`, `set_value(1000.0, true)`; `is_animating()` true; `current_color() == UiTheme.color("good")`; `advance(0.35)` -> `value_shown()` near 875.0 (eps 0.001; u = 0.5, eased 0.875); `advance(0.35)` -> near 1000.0, `is_animating()` false, `current_color() == c.base_color`. `test_roll_down_and_retarget`: from 1000 `set_value(500.0, true)`: colour "bad"; `advance(0.35)` -> near 937.5 + ... compute: from 1000 to 500, eased 0.875 -> 562.5 (assert near 562.5); then `set_value(0.0, true)` mid-animation starts from 562.5: `advance(0.35)` -> near `562.5 - 562.5 * 0.875 == 70.3125`. `test_number_mode`: `money_mode = false`, `prefix = "x"`, `suffix = "!"`, `set_value(7.4, false)` gives `text() == "x7!"`; 7.5 gives "x8!". `test_zero_dt`: `advance(0.0)` on a finished counter changes nothing.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_counter` last line is `GDTEST OK`."]),

 dict(id="GDU06", title="UI: speech banner with typewriter reveal", needs=["GDU01", "GDU31", HARN],
  files=["godot/ui/banner.gd", "godot/tests/test_ui_banner.gd"],
  goal="`UiBanner`: Dave's big peach speech banner across the top (port of the idea of src/art/banner.js): four peach bands with dithered boundaries, ink outline cut at the corners, a tail pointing at the speaker, text typed out at 40 characters per second.",
  read=[PLAN, TESTS, THEME, UTXT, "src/art/banner.js (read it all: bands, dither rows, outline, tail geometry, typewriter, 4 px grid G)"],
  steps=[
   r'''`godot/ui/banner.gd`: `class_name UiBanner`, `extends Control`. Signals `char_revealed(count: int)` and `finished`. Consts `G := 4`, `CHAR_W := 12` (VT323 28 px is monospaced), `LINE_H := 30`, `MAX_LINES := 3`, `CPS := 40.0`, `PEACH := ["#F8DCB8", "#F2C9A0", "#E8B085", "#D99A6C"]` (Strings; use `Color(PEACH[i])`). Vars: `full_text: String`, `lines: Array[String]`, `tail_x: float = -1.0`, `_reveal: float`, `_done: bool = true`, `_t: float`. `_init`: `size = Vector2(1232, 112)`, `mouse_filter = MOUSE_FILTER_IGNORE`.''',
   r'''`func max_chars() -> int: return maxi(1, int(floor((size.x - 6.0 * G) / CHAR_W)))`. `func say(text: String, tail: float = -1.0) -> void`: `full_text = text.to_upper()`, `tail_x = tail`, `lines = UiText.wrap(full_text, max_chars(), MAX_LINES)`, `_reveal = 0.0`, `_done = (total_chars() == 0)`, `queue_redraw()`. `func total_chars() -> int`: sum of `lines[i].length()`. `func visible_chars() -> int: return mini(int(floor(_reveal)), total_chars())`. `func advance(dt: float) -> void`: `_t += dt`; if not done: `var before := visible_chars()`; `_reveal += CPS * dt`; if `visible_chars() != before` emit `char_revealed(visible_chars())`; if `visible_chars() >= total_chars()` set `_done = true` and emit `finished` (once). `queue_redraw()`. `_process(dt)` calls `advance(dt)`. `func skip() -> void`: if not done, `_reveal = float(total_chars())`, `_done = true`, emit `char_revealed(total_chars())` then `finished`; `queue_redraw()`. `func is_done() -> bool: return _done`. `func clear() -> void`: `full_text = ""; lines = []; _done = true`.''',
   r'''`static func tail_bx(tail: float, w: float) -> int`: `var bx := int(round(tail / G)) * G - 16`; clamp to `[4 * G, int(w) - 7 * G]` and return (the tail's left x). For `tail < 0` the caller passes `size.x / 2.0`. Examples: `tail_bx(100.0, 1232.0) == 84`, `tail_bx(-500.0, 1232.0) == 16`, `tail_bx(5000.0, 1232.0) == 1204`.''',
   r'''`_draw()` (all with `draw_rect`, port of banner.js in this order; bandH = `size.y / 4`): (1) shadow `Rect2(G, G, size.x, size.y)` colour black alpha 0.35; (2) four band rects, band i filled with `Color(PEACH[i])`; then for boundary i in 0..2 at `y = (i + 1) * bandH` a row of G x G squares at every `2 * G` step along x, colour `PEACH[i]` when `(j + i) % 2 == 0` else `PEACH[i + 1]` (j = square index); (3) ink outline (colour "ink"), G thick: top and bottom `Rect2(G, 0, size.x - 2G, G)` / `Rect2(G, size.y - G, size.x - 2G, G)`, left and right `Rect2(0, G, G, size.y - 2G)` / `Rect2(size.x - G, G, G, size.y - 2G)`, plus the four inner corner squares at `(G, G)`, `(size.x - 2G, G)`, `(G, size.y - 2G)`, `(size.x - 2G, size.y - 2G)`; (4) the tail: `bx = tail_bx(tail_x if tail_x >= 0.0 else size.x / 2.0, size.x)`, for i in 0..4: `y = size.y + i * G`; fill `Rect2(bx + i * G, y, (5 - i) * G, G)` with `PEACH[3]`, then ink squares at `(bx + i * G, y)` and `(bx + 4 * G, y)` (each G x G); (5) the text: for each line k draw `lines[k].substr(0, remaining)` with `UiTheme.draw_text(self, ..., Vector2(3 * G, 3 * G + k * LINE_H), "body", UiTheme.color("ink"))` where `remaining` starts at `visible_chars()` and drops by each line's length; (6) while not done and `int(_t * 4.0) % 2 == 0`: a `2G x 2G` ink square as a cursor at the end of the last drawn line (x = `3 * G + CHAR_W * shown_length`).''',
   r'''`godot/tests/test_ui_banner.gd`: `test_tail`: the three examples above. `test_say_reveal`: `var b := UiBanner.new()`; connect `finished` and `char_revealed` into counters; `b.say("hello world")`; `b.full_text == "HELLO WORLD"`, `b.lines == ["HELLO WORLD"]`, `total_chars() == 11`, `visible_chars() == 0`, `is_done()` false; `advance(0.125)` (= 5 characters) -> `visible_chars() == 5`, the FIRST `char_revealed` value recorded is 5; `advance(10.0)` -> `visible_chars() == 11`, `is_done()`, `finished` count exactly 1; another `advance(1.0)` leaves finished at 1. `test_skip`: `say("abc")`, `skip()` -> done, `visible_chars() == 3`, finished 1; `skip()` again leaves finished at 1. `test_wrap_three_lines`: `b.size = Vector2(200, 112)` (max_chars = floor((200 - 24) / 12) = 14); `say("one two three four five six seven eight nine ten")`: `lines == ["ONE TWO THREE", "FOUR FIVE SIX", "SEVEN EIGHT..."]` (the text is too long for 3 lines, so the last kept line gets the dots). `test_empty`: `say("")` is done immediately with `total_chars() == 0`.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_banner` last line is `GDTEST OK`."]),

 # ------------------------------------------------------------------------------------------------ HUD parts
 dict(id="GDU21", title="UI: Gold Number Plate slots and CASH bar", needs=["GDU02", "GDU05"],
  files=["godot/ui/plate_row.gd", "godot/ui/cash_bar.gd", "godot/tests/test_ui_plates_cash.gd"],
  goal="Two HUD pieces for the bottom strip: `UiPlateRow` (the four Gold Number Plate slots, tappable for a hint) and `UiCashBar` (green CASH bar with the money figure rolling via UiCounter).",
  read=[PLAN, TESTS, THEME, TAPR, "godot/ui/counter.gd (GDU05)", "src/art/hud.js (plate codes FC SB HN HT, gold when won, grey when not) and docs/art/RSAMH_STYLE.md section 3"],
  steps=[
   r'''`godot/ui/plate_row.gd`: `class_name UiPlateRow`, `extends Control`. Signal `plate_tapped(key: String)`. `const KEYS: Array[String] = ["fatcat", "stable", "household", "hammer"]`, `const CODES := {"fatcat": "FC", "stable": "SB", "household": "HN", "hammer": "HT"}`. `var plates: Dictionary = {}`, `var _tap := UiTap.new()`. `_init`: `size = Vector2(280, 64)`, `mouse_filter = MOUSE_FILTER_STOP`. `func set_plates(p: Dictionary) -> void: plates = p; queue_redraw()`. `func is_won(key: String) -> bool: return plates.get(key, false) == true`. `func slot_rect(i: int) -> Rect2: return Rect2(i * 72, 0, 64, 64)` (a 64x64 touch cell). `func slot_at(pos: Vector2) -> int`: the slot index whose rect contains `pos`, else -1. `handle_event(ev)` (and `_gui_input` forwarding): left press `_tap.press("p%d" % slot)` ("" when -1); left release: if `_tap.release(...)` for the same slot and slot >= 0, emit `plate_tapped(KEYS[slot])`.''',
   r'''`UiPlateRow._draw()`: for each slot: the visible plate is `Rect2(cell.position + Vector2(4, 12), Vector2(56, 40))`; won: `UiTheme.draw_box(self, plate, UiTheme.color("gold"), UiTheme.color("ink"), 4, true)` with a 2 px "brassLight" highlight line along the top inside edge, code text colour "ink"; not won: fill "midgrey", code text colour "darkgrey". The two-letter code is drawn centred with role "h3" (16 px) at `plate.position + Vector2(0, 12)`, width `plate.size.x`.''',
   r'''`godot/ui/cash_bar.gd`: `class_name UiCashBar`, `extends Control`. `const TARGET := 100000.0` (the Fat Cat plate). `_init`: `size = Vector2(280, 44)`, `mouse_filter = MOUSE_FILTER_IGNORE`. A child `UiCounter` named "Counter" created in `_ready()`: `position = Vector2(88, 0)`, `size = Vector2(184, 44)`, `role = "h3"`, `align = HORIZONTAL_ALIGNMENT_RIGHT`, `money_mode = true`. `var cash: float`. `static func fill_ratio(c: float) -> float: return clampf(c / TARGET, 0.0, 1.0)`. `func set_cash(c: float, animate: bool = true) -> void`: `cash = c`; `$Counter.set_value(c, animate)`; `$Counter.base_color = UiTheme.color("bad") if c < 0.0 else UiTheme.color("white")`; `queue_redraw()`. `_draw()`: `UiTheme.draw_bar(self, Rect2(Vector2.ZERO, size), fill_ratio(cash), UiTheme.color("cashGreen"), UiTheme.color("cashDark"))`, then "CASH" with `UiTheme.draw_text(self, "CASH", Vector2(12, 14), "h3", UiTheme.color("cream"))`.''',
   r'''`godot/tests/test_ui_plates_cash.gd`: `test_slots`: `UiPlateRow.new()`: `slot_rect(0) == Rect2(0, 0, 64, 64)`, `slot_rect(3) == Rect2(216, 0, 64, 64)`, `slot_at(Vector2(70, 10)) == -1` (the 8 px gap), `slot_at(Vector2(80, 10)) == 1`, `slot_at(Vector2(300, 10)) == -1`. `test_won`: `set_plates({"fatcat": true, "stable": false})`: `is_won("fatcat")` true, `is_won("stable")` false, `is_won("hammer")` false. `test_tap`: connect `plate_tapped` to collect keys; press (80, 10) release (82, 12) gives `["stable"]`; press slot 1 and release on slot 2 (150, 10) gives nothing new; press in the gap (70, 10) release there: nothing new. `test_fill_ratio`: `UiCashBar.fill_ratio(50000.0)` near 0.5; `(-5.0)` is 0.0; `(250000.0)` is 1.0. `test_cash_bar`: add a `UiCashBar` to the tree (`tree().root.add_child`) so `_ready` runs; `set_cash(1500.0, false)`; `$Counter.text() == CoreFormat.money(1500)` (use `get_node("Counter")`); `set_cash(-20.0, false)`: counter `base_color == UiTheme.color("bad")`; free the node.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_plates_cash` last line is `GDTEST OK`."]),

 dict(id="GDU22", title="UI: torn-off calendar day sheet", needs=["GDU01"],
  files=["godot/ui/calendar_sheet.gd", "godot/tests/test_ui_calendar.gd"],
  goal="`UiCalendarSheet`: the torn-off wall-calendar sheet of the bottom HUD (weekday + month on a red band, big day-of-month number, tiny DAY n line). When the day changes the old sheet is torn off and flutters away (0.35 s).",
  read=[PLAN, TESTS, THEME, "src/art/calendar.js (day 1 of the year is a MONDAY: weekday of day d is (d - 1) % 7; 365-day year, no leap years)", "src/core/clock.js (MONTH_LENGTHS)"],
  steps=[
   r'''`godot/ui/calendar_sheet.gd`: `class_name UiCalendarSheet`, `extends Control`. Consts `MONTH_LENGTHS: Array[int] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]`, `MONTHS: Array[String] = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"]`, `WEEKDAYS: Array[String] = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"]`, `TEAR := 0.35`. `static func date_parts(day: int) -> Dictionary`: clamp `day` to 1..365; walk the months to find `month` (1..12) and `dom` (day of month); `weekday = (day - 1) % 7` (0 = MON). Return `{"month": m, "dom": d, "weekday": w}`.''',
   r'''Vars `day: int = 1`, `_prev_day: int = 0`, `_tear: float = 1.0` (1 = finished). `_init`: `size = Vector2(130, 114)`, `mouse_filter = MOUSE_FILTER_IGNORE`. `func set_day(d: int, animate: bool = true) -> void`: clamp to 1..365; if `d == day` do nothing; `_prev_day = day`; `day = d`; `_tear = 0.0 if animate else 1.0`; `queue_redraw()`. `func advance(dt: float) -> void`: if `_tear < 1.0`: `_tear = minf(1.0, _tear + dt / TEAR)`; `queue_redraw()`. `_process(dt)` calls `advance(dt)`. `func tear_progress() -> float: return _tear`. `func label_for(d: int) -> String`: `"%s %s" % [WEEKDAYS[p.weekday], MONTHS[p.month - 1]]`, e.g. "MON JAN". `func number_for(d: int) -> String`: `str(p.dom)`.''',
   r'''`_draw()`: first the sheet underneath for the current `day` at offset (0, 0) via a private `_sheet(offset: Vector2, d: int, alpha: float)`; then, while `_tear < 1.0`, the previous sheet via `_sheet(Vector2(70.0 * _tear, 50.0 * _tear), _prev_day, 1.0 - _tear)`. `_sheet`: paper box `UiTheme.draw_box(self, Rect2(offset, Vector2(130, 114)), paper (alpha applied), ink, 4, false)`; a jagged torn top edge: for k in 0..12 a 4 px ink triangle-ish step `draw_rect(Rect2(offset.x + k * 10.0, offset.y + (k % 2) * 4.0, 10.0, 4.0), ink)`; a red band `Rect2(offset + Vector2(4, 12), Vector2(122, 28))` in "enamelRed" with `label_for(d)` centred (role "h3", colour "white"); the big day number centred below with role "number" (48 px) colour "ink" at `offset + Vector2(0, 48)`, width 130; and `"DAY %d" % d` at the bottom with role "caption" colour "midgrey" centred at `offset + Vector2(0, 92)`.''',
   r'''`godot/tests/test_ui_calendar.gd`: `test_date_parts`: `date_parts(1) == {"month": 1, "dom": 1, "weekday": 0}`; `date_parts(31)` is month 1, dom 31, weekday 2; `date_parts(32)` is month 2, dom 1, weekday 3; `date_parts(59)` is month 2 dom 28; `date_parts(60)` is month 3, dom 1, weekday 3; `date_parts(365)` is month 12, dom 31, weekday 0; `date_parts(0)` equals `date_parts(1)`; `date_parts(400)` equals `date_parts(365)`. `test_labels`: `label_for(1) == "MON JAN"`, `label_for(32) == "THU FEB"`, `number_for(60) == "1"`, `number_for(365) == "31"`. `test_tear`: a new sheet `s`; `s.set_day(2, false)`: `day == 2`, `tear_progress() == 1.0`; `s.set_day(3, true)`: progress 0.0; `advance(0.175)` -> near 0.5; `advance(1.0)` -> 1.0; `set_day(3)` again (same day) does not restart the tear. `test_clamp`: `set_day(999, false)` gives `day == 365`; `set_day(-4, false)` gives 1.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_calendar` last line is `GDTEST OK`."]),

 dict(id="GDU29", title="UI: cash history and small sales chart", needs=["GDU01"],
  files=["godot/ui/cash_history.gd", "godot/ui/sales_chart.gd", "godot/tests/test_ui_chart.gd"],
  goal="The small white SALES chart of the bottom HUD and the ledger channel: `UiCashHistory` (a static recent-cash series) feeding `UiSalesChart` (a Control that plots a line).",
  read=[PLAN, TESTS, THEME, "docs/art/RSAMH_STYLE.md section 3 (white SALES chart panel)"],
  steps=[
   r'''`godot/ui/cash_history.gd`: `class_name UiCashHistory`, `extends RefCounted`, static only. `const MAX := 30`. `static var _days: Array[int] = []`, `static var _vals: Array[float] = []`. `static func record(day: int, cash: float) -> void`: if `_days` is not empty and `day == _days.back()` replace the last value; elif `_days` is not empty and `day < _days.back()` (a new or loaded game went back in time) clear both arrays then append; else append; then drop the oldest entries while there are more than `MAX`. `static func values(n: int = 14) -> Array[float]`: the last `n` values (all of them if fewer), oldest first. `static func count() -> int`. `static func reset() -> void` clears both.''',
   r'''`godot/ui/sales_chart.gd`: `class_name UiSalesChart`, `extends Control`. `_init`: `size = Vector2(320, 114)`, `mouse_filter = MOUSE_FILTER_IGNORE`. `var values: Array[float] = []`. `func set_values(v: Array) -> void`: copy into `values` as floats; `queue_redraw()`. `func plot_rect() -> Rect2: return Rect2(12, 34, size.x - 24, size.y - 46)`. `static func scale_points(vals: Array, r: Rect2) -> PackedVector2Array`: empty input -> empty; one value -> one point at `r.get_center()`; otherwise `x = r.position.x + i * r.size.x / (n - 1)` and `y = r.end.y - (v - lo) / (hi - lo) * r.size.y` where `lo`/`hi` are the min/max of the values; when `hi == lo` every `y` is `r.position.y + r.size.y / 2.0`.''',
   r'''`UiSalesChart._draw()`: `UiTheme.draw_box(self, Rect2(Vector2.ZERO, size), UiTheme.color("chartWhite"), UiTheme.color("ink"), 4, true)`; the title "SALES" (role "h3", colour "ink") at (12, 10); three faint horizontal grid lines in "paperShade" across `plot_rect()` at 0, 50 and 100 %; if there are at least 2 points `draw_polyline(points, UiTheme.color("cashDark"), 3.0)` and a 6x6 "bad"/"good" square on the last point (good when the last value >= the first, else bad); with fewer than 2 points draw the caption "no sales yet" (role "caption", colour "midgrey") centred in the plot rect.''',
   r'''`godot/tests/test_ui_chart.gd`: `test_history_record`: `UiCashHistory.reset()`; `record(1, 100.0)`, `record(2, 150.0)`, `record(2, 160.0)` (same day replaces): `values() == [100.0, 160.0]` and `count() == 2`. `test_history_cap`: reset, record days 1..40 with cash == day: `count() == 30`, `values(3) == [38.0, 39.0, 40.0]`, `values(100).size() == 30`. `test_history_rewind`: reset, record 5 days then `record(2, 9.0)` (earlier day): `values() == [9.0]`. `test_scale_points`: `UiSalesChart.scale_points([0.0, 10.0, 5.0], Rect2(0, 0, 100, 50))` equals `PackedVector2Array([Vector2(0, 50), Vector2(50, 0), Vector2(100, 25)])`; `scale_points([3.0, 3.0], Rect2(0, 0, 100, 50))` equals `PackedVector2Array([Vector2(0, 25), Vector2(100, 25)])`; `scale_points([5.0], Rect2(0, 0, 100, 50)) == PackedVector2Array([Vector2(50, 25)])`; `scale_points([], Rect2(0, 0, 100, 50)).size() == 0`. `test_chart_values`: `set_values([1, 2, 3])` leaves `values == [1.0, 2.0, 3.0]`; `plot_rect() == Rect2(12, 34, 296, 68)`. End `test_history_*` tests with `UiCashHistory.reset()` so other tests start clean.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_chart` last line is `GDTEST OK`."]),

 dict(id="GDU19", title="UI: CarPortrait widget API stub (placeholder drawing)", needs=["GDU01", DATA],
  files=["godot/ui/car_portrait.gd", "godot/tests/test_car_portrait.gd"],
  goal="`CarPortrait`, the single API for 'show this car here' (HUD slot, shop detail, bookings). For now it draws a coloured placeholder car with the model name; the GDA cards later swap the inside for the real 3D `CarView` WITHOUT changing this API.",
  read=[PLAN, TESTS, THEME, "godot/autoload/data.gd (GDF03: `Data.car_by_id(id) -> Dictionary` ({} if unknown), `Data.paint_of(id) -> String` hex)", "docs/GODOT.md section 'Art in Godot' (CarView in a SubViewport: paint colour set at runtime, wear 0..3)"],
  steps=[
   r'''`godot/ui/car_portrait.gd`: `class_name CarPortrait`, `extends Control`. `_init`: `size = Vector2(200, 114)`, `mouse_filter = MOUSE_FILTER_IGNORE`. Private `_id: String = ""`, `_paint: Color = Color(0.53, 0.53, 0.53)`, `_wear: int = 0`. API (the contract; never rename): `func set_car(id: String, paint: Color, wear: int = 0) -> void` (`wear` clamped to 0..3; `queue_redraw()`), `func clear() -> void` (id `""`), `func get_car_id() -> String`, `func get_paint() -> Color`, `func get_wear() -> int`, `func body_color() -> Color: return _paint.darkened(0.12 * _wear)`. `func display_name() -> String`: `""` when no car; else `var m := Data.car_by_id(_id)`; the model's `name` upper-cased, or `_id.to_upper()` when the model is unknown. `static func wear_for(condition: float) -> int: return clampi(int(floor((10.0 - condition) / 2.5)), 0, 3)` (condition 10 = pristine -> 0, condition 0 -> 3).''',
   r'''`_draw()`: frame: `UiTheme.draw_box(self, Rect2(Vector2.ZERO, size), UiTheme.color("lightblue"), UiTheme.color("ink"), 4, true)`; three dither rows at y = `size.y * k / 4` for k = 1..3 of 4x4 squares every 8 px in `UiTheme.color("lightblue").lightened(0.18)`. If there is no car, draw "NO CAR" (role "h3", colour "cream") centred. Otherwise the placeholder car, all relative to `size`: body `Rect2(size.x * 0.17, size.y * 0.50, size.x * 0.66, size.y * 0.22)` in `body_color()`; cabin `Rect2(size.x * 0.32, size.y * 0.33, size.x * 0.34, size.y * 0.18)` in `body_color().lightened(0.1)`; windows two `Rect2` inside the cabin in "cyan"; two wheels `draw_circle` at `(size.x * 0.30, size.y * 0.74)` and `(size.x * 0.70, size.y * 0.74)` radius `size.y * 0.10` in "black" with a smaller "lightgrey" hub; if `_wear >= 2` two small rust patches (4x4 squares in "orange") on the body, if `_wear == 3` four. The name `display_name()` is drawn at the bottom on a 24 px "cream" plaque (role "caption", colour "ink", centred, `UiText.ellipsize` not needed: the plaque is clipped by `clip_contents = true` set in `_init`).''',
   r'''`godot/tests/test_car_portrait.gd`: `test_api`: `var p := CarPortrait.new()`; `p.set_car("t1_allergy", Color("#8E8455"), 2)`: `get_car_id() == "t1_allergy"`, `get_paint() == Color("#8E8455")`, `get_wear() == 2`; `display_name() == "AUSTEN ALLERGY"` (the real Data entry); `body_color().r` near `Color("#8E8455").darkened(0.24).r` (eps 0.0001). `test_clamp`: `set_car("t1_allergy", Color.RED, 9)` gives wear 3; `set_car("t1_allergy", Color.RED, -4)` gives 0. `test_unknown_and_clear`: `set_car("zzz", Color.RED)` -> `display_name() == "ZZZ"`; `clear()` -> `get_car_id() == ""` and `display_name() == ""`. `test_wear_for`: `wear_for(10.0) == 0`, `wear_for(8.0) == 0`, `wear_for(7.5) == 1`, `wear_for(5.0) == 2`, `wear_for(2.5) == 3`, `wear_for(0.0) == 3`, `wear_for(12.0) == 0`. `test_default_size`: a new CarPortrait has `size == Vector2(200, 114)`.'''],
  accept=["`sh tools/godot/gtest.sh test_car_portrait` last line is `GDTEST OK`."],
  oos=["Any 3D, SubViewport or Blender work (the GDA cards own that)."]),

 dict(id="GDU07", title="UI: bottom HUD strip (UiHud)", needs=["GDU05", "GDU19", "GDU21", "GDU22", "GDU29", GAME, DATA],
  files=["godot/ui/hud.gd", "godot/tests/test_ui_hud.gd"],
  goal="`UiHud`: the permanent bottom strip (stage y 590-720, 1280x130): four Gold Number Plate slots, CASH bar, selected-car portrait, torn-off calendar day, small sales chart, REP and BUZZ bars. It only READS the game state.",
  read=[PLAN, TESTS, THEME, "godot/ui/plate_row.gd, cash_bar.gd, calendar_sheet.gd, sales_chart.gd, cash_history.gd, car_portrait.gd (GDU21, GDU22, GDU29, GDU19)", "docs/art/RSAMH_STYLE.md section 3 and src/art/hud.js (rep/buzz bars)", "godot/autoload/game.gd (GDF10: signals `changed`, `day_advanced`; `Game.state`)"],
  steps=[
   r'''`godot/ui/hud.gd`: `class_name UiHud`, `extends Control`. Signals `plate_tapped(key: String)`. `_init`: `size = Vector2(1280, 130)`, `mouse_filter = MOUSE_FILTER_PASS`. `func _ready() -> void: build()`. `func build() -> void` (idempotent: return at once when a child named "Plates" exists) creates children with these names and rects (local coordinates): `Plates` UiPlateRow at (24, 6) size (280, 64); `Cash` UiCashBar at (24, 78) size (280, 44); `Portrait` CarPortrait at (324, 8) size (300, 114); `Calendar` UiCalendarSheet at (640, 8) size (130, 114); `Chart` UiSalesChart at (786, 8) size (320, 114). Connect `Plates.plate_tapped` to re-emit `plate_tapped`.''',
   r'''State: `var _game: Object = null`, `var _rep: float`, `var _buzz: float`, `var _selected_id: String = ""`. `func bind(game: Object) -> void`: store it; `game.changed.connect(_on_changed)` (if not already connected); `refresh(game.state)`. `func _on_changed() -> void: refresh(_game.state)`. `func set_selected_car(car_id: String) -> void: _selected_id = car_id; if _game != null: refresh(_game.state)`. `func refresh(state: Dictionary) -> void`: `build()`; `Plates.set_plates(state.get("plates", {}))`; `var cash := float(state.get("cash", 0))`; `Cash.set_cash(cash)`; `var day := int(state.get("day", 1))`; `Calendar.set_day(day)`; `UiCashHistory.record(day, cash)`; `Chart.set_values(UiCashHistory.values(14))`; `_rep = float(state.get("reputation", 0))`; `_buzz = float(state.get("buzz", 0))`; the portrait car: pick the car in `state.get("cars", [])` whose `id == _selected_id`, else the first car with `owned == true`, else the first car, else none; `Portrait.set_car(car.modelId, Color(Data.paint_of(car.modelId)), CarPortrait.wear_for(float(car.condition)))` or `Portrait.clear()`. `queue_redraw()`.''',
   r'''`_draw()`: background `draw_rect(Rect2(Vector2.ZERO, size), UiTheme.color("hudBg"))`, a 4 px "hudEdge" line along the top. REP and BUZZ at x = 1122: `UiTheme.draw_text(self, "REP %d" % int(round(_rep)), Vector2(1122, 12), "h3", UiTheme.color("white"))` and a bar `UiTheme.draw_bar(self, Rect2(1122, 36, 134, 14), _rep / 100.0, UiTheme.color("good"))`; the same for "BUZZ %d" at y = 62 with the bar at y = 86 using colour "warn". Public helper `func portrait_car_id() -> String: return $Portrait.get_car_id()` (use `get_node("Portrait")`).''',
   r'''`godot/tests/test_ui_hud.gd` builds its own state inline (it does not use TestFakeGame): `{"day": 3, "cash": 5000, "reputation": 40, "buzz": 12, "plates": {"fatcat": true, "stable": false, "household": false, "hammer": false}, "cars": [{"id": "c1", "modelId": "t1_allergy", "owned": false, "condition": 5.0}, {"id": "c2", "modelId": "t1_robbin", "owned": true, "condition": 10.0}]}`. `test_layout`: `UiHud.new()` added to `tree().root`; `size == Vector2(1280, 130)`; children `Plates`, `Cash`, `Portrait`, `Calendar`, `Chart` exist (`get_node_or_null` not null) with positions (24, 6), (24, 78), (324, 8), (640, 8), (786, 8); free it. `test_refresh`: `UiCashHistory.reset()`; `h.refresh(state)`: `get_node("Plates").is_won("fatcat")` true; `get_node("Calendar").day == 3`; `get_node("Cash").cash == 5000.0`; the portrait shows the first OWNED car: `portrait_car_id() == "t1_robbin"`; `get_node("Portrait").get_wear() == 0`; `UiCashHistory.count() == 1`; `get_node("Chart").values == [5000.0]`. `test_selected_car`: `set_selected_car("c1")` then `refresh(state)`: `portrait_car_id() == "t1_allergy"` and wear 2 (condition 5.0). `test_no_cars`: a state with `"cars": []` gives `portrait_car_id() == ""`. `test_bind`: define in the test file a tiny inner helper class? Not needed: build a `Node` with a script from source: `var s := GDScript.new(); s.source_code = "extends Node\nsignal changed\nvar state := {}\n"; s.reload(); var g := Node.new(); g.set_script(s); g.state = state`; `h.bind(g)` refreshes immediately (`get_node("Calendar").day == 3`); change `g.state = {"day": 4, "cash": 1.0}` and `g.changed.emit()`: calendar day 4; free `g` and `h`. End each test with `UiCashHistory.reset()`.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_hud` last line is `GDTEST OK`."]),

 dict(id="GDU18", title="UI: scrolling list widget (drag, fling, tap)", needs=["GDU01", "GDU02"],
  files=["godot/ui/list.gd", "godot/tests/test_ui_list.gd"],
  goal="`UiList`: a vertical list that scrolls by dragging (phones), flings, mouse wheel and keys, and selects a row by TAP (not after a drag). Port of the ScrollList model in src/ui/kit_hits.js. The owner draws the rows through a Callable.",
  read=[PLAN, TESTS, TAPR, "src/ui/kit_hits.js class ScrollList (read it all; the numbers 8 px drag threshold, velocity in px per ms, decay 0.95 per 16 ms are copied)"],
  steps=[
   r'''`godot/ui/list.gd`: `class_name UiList`, `extends Control`. Signal `row_tapped(index: int)`. Vars: `row_h: int = 72`, `count: int = 0`, `offset: float = 0.0`, `selected: int = -1`, `row_painter: Callable` (called as `row_painter.call(self, index, rect, is_selected)` from inside `_draw()`; `rect` is the row's `Rect2` in this control's coordinates; when the Callable is not valid a default painter draws the row number), `vel: float = 0.0`, `dragging: bool = false`, private `_start_y`, `_last_y`, `_last_t` (floats), `_tap := UiTap.new()`, `_press_row: int = -1`. `_init`: `size = Vector2(300, 320)`, `clip_contents = true`, `mouse_filter = MOUSE_FILTER_STOP`.''',
   r'''Model (exact port): `func max_offset() -> float: return maxf(0.0, count * row_h - size.y)`. `func set_count(n: int) -> void: count = n; offset = clampf(offset, 0.0, max_offset()); selected = mini(selected, n - 1); queue_redraw()`. `func scroll_by(dy: float) -> void: offset = clampf(offset + dy, 0.0, max_offset()); queue_redraw()`. `func begin_drag(y: float, now_ms: float) -> void`: `_start_y = y; _last_y = y; _last_t = now_ms; dragging = false; vel = 0.0`. `func drag_to(y: float, now_ms: float) -> void`: if `absf(y - _start_y) > 8.0` then `dragging = true`; if not dragging return; `scroll_by(_last_y - y)`; `vel = (_last_y - y) / maxf(1.0, now_ms - _last_t)`; `_last_y = y; _last_t = now_ms`. `func end_drag() -> bool`: `var tapped := not dragging`; if tapped `vel = 0.0`; `dragging = false`; return `tapped`. `func advance_ms(dt_ms: float) -> void`: if `dragging` return; if `absf(vel) <= 0.01` { `vel = 0.0`; return }; `scroll_by(vel * dt_ms)`; `vel *= pow(0.95, dt_ms / 16.0)`; if `offset <= 0.0 or offset >= max_offset()` { `vel = 0.0` }; if `absf(vel) <= 0.01` { `vel = 0.0` }. `func advance(dt: float) -> void: advance_ms(dt * 1000.0)`; `_process(dt)` calls `advance(dt)`.''',
   r'''Geometry: `func row_at(local_y: float) -> int`: -1 when `local_y < 0` or `>= size.y`; `idx = int(floor((local_y + offset) / row_h))`; -1 when `idx < 0` or `idx >= count`. `func row_rect(i: int) -> Rect2: return Rect2(0.0, i * row_h - offset, size.x, row_h)`. `func visible_range() -> Vector2i`: `Vector2i(0, -1)` when `count == 0`; else `first = int(floor(offset / row_h))`, `last = mini(count - 1, int(ceil((offset + size.y) / row_h)) - 1)`. `func ensure_visible(i: int) -> void`: `var top := i * row_h`; if `top < offset` `scroll_by(top - offset)`; elif `top + row_h > offset + size.y` `scroll_by(top + row_h - offset - size.y)`. `func select(i: int, emit: bool = false) -> void`: `selected = clampi(i, -1, count - 1)`; `ensure_visible` when >= 0; `queue_redraw()`; if `emit` and `selected >= 0` emit `row_tapped(selected)`. `func move_selection(d: int) -> void`: `select(clampi(selected + d, 0, count - 1))` (when `count == 0` do nothing).''',
   r'''Input (`_gui_input` forwards to `handle_event(ev)`): `now = Time.get_ticks_msec()` as float. Left press: `_press_row = row_at(ev.position.y)`; `_tap.press("r%d" % _press_row if _press_row >= 0 else "")`; `begin_drag(ev.position.y, now)`. `InputEventMouseMotion` with `(ev.button_mask & MOUSE_BUTTON_MASK_LEFT) != 0`: `drag_to(ev.position.y, now)`. Left release: `var tapped := end_drag()`; `var r := row_at(ev.position.y)`; `var hit := _tap.release("r%d" % r if r >= 0 else "")`; if `tapped and hit` then `select(r)` and emit `row_tapped(r)`. Wheel up/down (`MOUSE_BUTTON_WHEEL_UP` / `MOUSE_BUTTON_WHEEL_DOWN`, pressed): `scroll_by(-row_h / 2.0)` / `scroll_by(row_h / 2.0)`. Keys: KEY_UP -> `move_selection(-1)`, KEY_DOWN -> `move_selection(1)`.''',
   r'''`_draw()`: for `i` in `visible_range()`: `row_painter.call(self, i, row_rect(i), i == selected)` when the Callable is valid, else `draw_string(ThemeDB.fallback_font, row_rect(i).position + Vector2(8, 24), str(i))`. When `max_offset() > 0.0` draw a 6 px wide "midgrey" scroll thumb at the right edge: height `size.y * size.y / (count * row_h)` (at least 24), y = `offset / max_offset() * (size.y - height)`.''',
   r'''`godot/tests/test_ui_list.gd`: every test builds its own `UiList` `l` with `count = 10`, `row_h = 72`, `size = Vector2(300, 320)` (so no state leaks between tests). `test_model`: `max_offset() == 400.0`; `visible_range() == Vector2i(0, 4)`; `scroll_by(100.0)`: offset 100.0, `visible_range() == Vector2i(1, 5)`, `row_at(10.0) == 1`; `scroll_by(9999.0)` -> 400.0; `scroll_by(-9999.0)` -> 0.0; `row_at(-1.0) == -1`; `row_at(400.0) == -1`; with `count = 2` `row_at(300.0) == -1` (past the last row). `test_rect_and_set_count`: offset 100: `row_rect(2) == Rect2(0, 44, 300, 72)`; `set_count(3)` clamps the offset to 0.0 (max is 216 - 320 < 0 -> 0). `test_tap_vs_drag`: `begin_drag(100.0, 0.0)`, `drag_to(104.0, 10.0)` leaves `dragging == false`, `end_drag() == true`; `begin_drag(100.0, 0.0)`, `drag_to(80.0, 10.0)`: `dragging`, offset 20.0, `vel` near 2.0; `end_drag() == false`. `test_fling`: continuing that state (`vel` 2.0, offset 20.0): `advance_ms(16.0)`: offset near 52.0 and `vel` near 1.9; at the end of the list the velocity is zeroed (`scroll_by(9999.0)` then `vel = 1.0`, `advance_ms(16.0)` -> `vel == 0.0`). `test_ensure_visible_select`: offset 0: `ensure_visible(9)` -> offset 400.0 (`9 * 72 + 72 - 320 = 400`); `ensure_visible(0)` -> 0.0; `select(3)` -> `selected == 3`; `select(99)` -> 9; `select(-5)` -> -1. `test_tap_signal`: collect `row_tapped`; press at (10, 100) (row 1) release at (12, 102) -> `[1]` and `selected == 1`; press row 1, release on row 2 (10, 170) -> nothing new; press, motion to a point 30 px away, release -> no tap (build a motion event: `InputEventMouseMotion.new()` with `position` and `button_mask = MOUSE_BUTTON_MASK_LEFT`). `test_painter`: set `row_painter = func(_l, _i, _r, _s): pass`; calling `queue_redraw()` must not error (`ok(row_painter.is_valid(), "valid")`).'''],
  accept=["`sh tools/godot/gtest.sh test_ui_list` last line is `GDTEST OK`."]),

 # ------------------------------------------------------------------------------------------------ FX
 dict(id="GDU20", title="UI: screen shake, flash and pop FX helper", needs=["GDU01", HARN],
  files=["godot/ui/fx.gd", "godot/tests/test_ui_fx.gd"],
  goal="`UiFx`: Tween-based juice used by every scene: shake any Control/Node2D, flash the screen, pop-scale a node. Deterministic (no random numbers), and testable with `Tween.custom_step`.",
  read=[PLAN, TESTS, "src/ui/screenfx.js (shake 300 ms, flash 180 ms) and src/ui/tokens.js MOTION"],
  steps=[
   r'''`godot/ui/fx.gd`: `class_name UiFx`, `extends RefCounted`, static, typed. `static func shake_offsets(strength: float, steps: int) -> Array[Vector2]`: for `i` in `0..steps-1`: `amp = strength * (1.0 - float(i) / float(steps))`; offset `Vector2(sin(i * 2.1) * amp, cos(i * 3.3) * amp * 0.6)`. (No randomness: the same call always gives the same list.) For `steps <= 0` return `[]`.''',
   r'''`static func shake(node: CanvasItem, strength: float = 8.0, duration: float = 0.3) -> Tween`: remember `var home: Vector2 = node.position`; `var tw := node.create_tween()`; for each offset of `shake_offsets(strength, 8)` add `tw.tween_property(node, "position", home + off, duration / 9.0)`; finally `tw.tween_property(node, "position", home, duration / 9.0)`; return `tw`. (The node must be a Control or Node2D: both have `position`.) If `strength <= 0.0` return a tween with a single zero-length step to `home`.''',
   r'''`static func flash(host: Control, color: Color = Color(1, 1, 1, 1), duration: float = 0.18, peak: float = 0.6) -> Tween`: create `var r := ColorRect.new()`, `r.name = "FxFlash"`, `r.color = Color(color.r, color.g, color.b, 0.0)`, `r.mouse_filter = Control.MOUSE_FILTER_IGNORE`, `r.set_anchors_preset(Control.PRESET_FULL_RECT)`, `host.add_child(r)`; `var tw := r.create_tween()`; `tw.tween_property(r, "color:a", peak, duration * 0.25)`; `tw.tween_property(r, "color:a", 0.0, duration * 0.75)`; `tw.tween_callback(r.queue_free)`; return `tw`. `static func pop(node: CanvasItem, amount: float = 1.15, duration: float = 0.18) -> Tween`: `node.pivot_offset = node.size / 2.0` when it is a Control; `var tw := node.create_tween()`; tween `scale` to `Vector2(amount, amount)` over `duration * 0.4` (linear) and then back to `Vector2.ONE` over `duration * 0.6`; return `tw`.''',
   r'''`godot/tests/test_ui_fx.gd`: `test_offsets`: `shake_offsets(10.0, 5).size() == 5`; the first offset equals `Vector2(0.0, 6.0)` (i = 0: sin 0 = 0, cos 0 = 1, amp 10, 0.6 factor); every offset's `length()` is at most 10.0 + 0.001; `shake_offsets(10.0, 0) == []`; two calls give identical arrays. `test_shake_returns_home`: a `Control` `c` with `position = Vector2(100, 50)` added to the tree; `var tw := UiFx.shake(c, 8.0, 0.3)`; `tw.custom_step(0.1)` (the node has moved or still near home, no assertion on position); `tw.custom_step(5.0)`; `c.position == Vector2(100, 50)` (back home); free `c`. `test_flash`: a host Control in the tree; `var tw := UiFx.flash(host)`; the host has a child named "FxFlash"; `tw.custom_step(5.0)` finishes; the child `is_queued_for_deletion()`; free host. `test_pop`: a Control `c` with `size = Vector2(40, 40)` in the tree; `var tw := UiFx.pop(c)`; `c.pivot_offset == Vector2(20, 20)`; `tw.custom_step(5.0)`; `c.scale == Vector2.ONE`; free it.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_fx` last line is `GDTEST OK`."]),

 dict(id="GDU26", title="UI: particle helpers (cash, confetti, smoke)", needs=["GDU01", HARN],
  files=["godot/ui/particles.gd", "godot/tests/test_ui_particles.gd"],
  goal="`UiParticles`: one-shot GPUParticles2D bursts built entirely in code (no texture files): falling cash, confetti and smoke puffs. Each burst frees itself when finished.",
  read=[PLAN, TESTS, "src/ui/particles.js (what the JS bursts look like: counts, colours, gravity)"],
  steps=[
   r'''`godot/ui/particles.gd`: `class_name UiParticles`, `extends RefCounted`, static, typed. `static var _tex: ImageTexture`. `static func square_texture() -> ImageTexture`: build once: `var img := Image.create(4, 4, false, Image.FORMAT_RGBA8)`, `img.fill(Color.WHITE)`, `_tex = ImageTexture.create_from_image(img)`; return the cached one afterwards. `static func _base(parent: Node, pos: Vector2, amount: int, lifetime: float) -> GPUParticles2D`: `var p := GPUParticles2D.new()`, `p.position = pos`, `p.amount = amount`, `p.lifetime = lifetime`, `p.one_shot = true`, `p.explosiveness = 0.9`, `p.texture = square_texture()`, `p.emitting = true`, `p.finished.connect(p.queue_free)`, `parent.add_child(p)`, return `p`.''',
   r'''`static func cash(parent: Node, pos: Vector2) -> GPUParticles2D`: `_base(parent, pos, 24, 1.2)` with a `ParticleProcessMaterial` `m`: `m.direction = Vector3(0, -1, 0)`, `m.spread = 60.0`, `m.initial_velocity_min = 180.0`, `m.initial_velocity_max = 320.0`, `m.gravity = Vector3(0, 600, 0)`, `m.scale_min = 2.0`, `m.scale_max = 3.0`, `m.color = UiTheme.color("cashGreen")`; assign `p.process_material = m`. `static func confetti(parent: Node, pos: Vector2) -> GPUParticles2D`: `_base(parent, pos, 60, 1.8)`, material: direction (0, -1, 0), spread 80.0, velocity 200..420, gravity (0, 500, 0), scale 1.5..3.0, and a `color_ramp` `GradientTexture1D` whose `gradient` has 4 colours: `Color("#E8B923")`, `Color("#D9483B")`, `Color("#3FAE49")`, `Color("#70A4B2")` at offsets 0.0, 0.33, 0.66, 1.0 and `m.color_initial_ramp = ramp_texture` (random colour per particle). `static func smoke(parent: Node, pos: Vector2) -> GPUParticles2D`: `_base(parent, pos, 12, 1.6)`, explosiveness 0.2, material: direction (0, -1, 0), spread 20.0, velocity 20..50, gravity (0, -30, 0), scale 4.0..7.0, `m.color = Color(0.6, 0.6, 0.6, 0.5)`.''',
   r'''`godot/tests/test_ui_particles.gd` (every `near` uses eps 0.001): `test_texture`: `UiParticles.square_texture()` is not null, 4x4 (`get_width() == 4`), and the second call returns the same object. `test_cash`: a host `Node2D` in the tree; `var p := UiParticles.cash(host, Vector2(10, 20))`: `p.position == Vector2(10, 20)`, `p.amount == 24`, `p.one_shot`, `p.lifetime` near 1.2, `p.process_material is ParticleProcessMaterial`, `p.texture != null`, `p.get_parent() == host`. `test_confetti`: `amount == 60`, lifetime near 1.8, `(p.process_material as ParticleProcessMaterial).color_initial_ramp != null`. `test_smoke`: `amount == 12`, `explosiveness` near 0.2, the material's `gravity.y` near -30.0. Free `host` at the end of each test.'''],
  accept=["`sh tools/godot/gtest.sh test_ui_particles` last line is `GDTEST OK`."]),

 # ------------------------------------------------------------------------------------------------ main scene
 dict(id="GDU30", title="UI: SceneHost (go, push, pop)", needs=[HARN],
  files=["godot/ui/scene_host.gd", "godot/tests/test_scene_host.gd"],
  goal="`SceneHost`: a plain node (NOT an autoload) that owns the room/scene stack. `go` replaces everything, `push` stacks a scene on top (the one below is hidden and paused), `pop` returns. Scenes may define optional hooks `enter(params)`, `exit()`, `resume()`.",
  read=[PLAN, TESTS, "src/ui/scenes.js (the JS scene stack: go / push / pop)"],
  steps=[
   r'''`godot/ui/scene_host.gd`: `class_name SceneHost`, `extends Control`. Signal `changed(scene: Node)`. `var _stack: Array[Node] = []`. `_init`: `mouse_filter = MOUSE_FILTER_IGNORE`. `func _make(scene: Variant) -> Node`: a `String` path -> `(load(scene) as PackedScene).instantiate()`; a `PackedScene` -> `instantiate()`; a `Node` -> itself; anything else (or a missing file) -> `push_error("SceneHost: cannot make scene")` and `null`. `func current() -> Node: return _stack.back() if not _stack.is_empty() else null`. `func depth() -> int: return _stack.size()`.''',
   r'''`func push(scene: Variant, params: Dictionary = {}) -> Node`: `var n := _make(scene)`; if null return null; if the stack is not empty hide the top: `top.visible = false` (when it is a CanvasItem) and `top.process_mode = Node.PROCESS_MODE_DISABLED`; `if n is Control: (n as Control).set_anchors_preset(Control.PRESET_FULL_RECT)`; `add_child(n)`; `_stack.append(n)`; `if n.has_method("enter"): n.call("enter", params)`; `changed.emit(n)`; return `n`. `func go(scene: Variant, params: Dictionary = {}) -> Node`: remove every stack entry (for each, in reverse: `if has_method("exit")` call it; `remove_child`; `queue_free()`), clear the stack, then `return push(scene, params)`. `func pop() -> Node`: if `_stack.size() <= 1` return `current()` unchanged; else take the top: `exit` hook, `remove_child`, `queue_free`; the new top: `visible = true`, `process_mode = Node.PROCESS_MODE_INHERIT`, call its `resume()` hook if present; `changed.emit(top)`; return the new top.''',
   r'''`godot/tests/test_scene_host.gd`: helper in the test file: `func _probe() -> Control:` builds a `GDScript` with `source_code = "extends Control\nvar events: Array = []\nfunc enter(p: Dictionary) -> void:\n\tevents.append(\"enter\")\nfunc exit() -> void:\n\tevents.append(\"exit\")\nfunc resume() -> void:\n\tevents.append(\"resume\")\n"`, `reload()`, creates a `Control`, `set_script(s)`, returns it. Tests (host `h := SceneHost.new()` added to `tree().root`, freed at the end): `test_go`: `var a := _probe()`; `h.go(a)` returns `a`; `h.current() == a`; `h.depth() == 1`; `a.events == ["enter"]`; `a.get_parent() == h`; a second `var b := _probe(); h.go(b)`: `a.events == ["enter", "exit"]`, `a.is_queued_for_deletion()`, `h.depth() == 1`, `h.current() == b`. `test_push_pop`: `go(a)`; `push(b)`: `h.depth() == 2`, `a.visible == false`, `a.process_mode == Node.PROCESS_MODE_DISABLED`, `h.current() == b`; `h.pop()` returns `a`: `a.visible == true`, `a.process_mode == Node.PROCESS_MODE_INHERIT`, `a.events == ["enter", "resume"]`, `b.events == ["enter", "exit"]`, `h.depth() == 1`; `h.pop()` again keeps `a` (depth stays 1). `test_signal_and_params`: collect `changed` emissions during `go(a)`, `push(b)`, `pop()` (3 emissions); a PackedScene also works: `var ps := PackedScene.new(); ps.pack(Control.new())`... use `ps.pack(c)` with a fresh Control `c` (call `c.free()` after packing), then `h.push(ps)` returns a Control. `test_bad_scene`: `h.push(42)` returns null and depth is unchanged.'''],
  accept=["`sh tools/godot/gtest.sh test_scene_host` last line is `GDTEST OK`."]),

 dict(id="GDU08", title="UI: main.tscn Stage, layers, safe area", needs=["GDU04", "GDU06", "GDU07", "GDU30", "GDU28", "GDU01"],
  files=["godot/scenes/main.tscn", "godot/scenes/main.gd", "godot/tests/test_main.gd"],
  goal="The root scene: a background layer that fills any window, a centred 1280x720 `Stage` holding everything interactive (SceneHost, HUD, banner, toasts, tooltip, fade layer), and safe-area maths for iPhone notches. GDF11's `run/main_scene` may point here later.",
  read=[PLAN, TESTS, "docs/GODOT.md sections 'Engine and layout' and 'Layout zones'", "godot/ui/scene_host.gd, hud.gd, banner.gd, toast.gd, tooltip.gd (GDU30, GDU07, GDU06, GDU04)", FAKE],
  steps=[
   r'''`godot/scenes/main.tscn` (text scene): `[gd_scene load_steps=2 format=3]`, `[ext_resource type="Script" path="res://scenes/main.gd" id="1"]`, root `[node name="Main" type="Control"]` with `layout_mode = 3`, `anchors_preset = 15`, `anchor_right = 1.0`, `anchor_bottom = 1.0`, `script = ExtResource("1")`. Everything else is built in code by `main.gd`.''',
   r'''`godot/scenes/main.gd`: `class_name Main`, `extends Control`. Consts `STAGE := Vector2(1280, 720)`. Static maths: `static func stage_position(canvas: Vector2) -> Vector2`: `Vector2(floorf(maxf(0.0, canvas.x - 1280.0) / 2.0), floorf(maxf(0.0, canvas.y - 720.0) / 2.0))`. `static func safe_insets(screen: Vector2, safe: Rect2, canvas: Vector2) -> Dictionary`: `s = canvas.x / screen.x`; `{"left": safe.position.x * s, "top": safe.position.y * s, "right": (screen.x - safe.end.x) * s, "bottom": (screen.y - safe.end.y) * s}`. `static func stage_insets(ins: Dictionary, stage_pos: Vector2) -> Dictionary`: `{"left": maxf(0.0, ins.left - stage_pos.x), "right": maxf(0.0, ins.right - stage_pos.x), "top": maxf(0.0, ins.top - stage_pos.y), "bottom": maxf(0.0, ins.bottom - stage_pos.y)}` (how far the safe area cuts INTO the stage).''',
   r'''`func _ready() -> void`: build the tree (names exact): `Backdrop` ColorRect (full rect, colour `UiTheme.color("ink")`, mouse ignore); `Stage` Control (`size = STAGE`) with children, in this draw order: `Scenes` (SceneHost, full rect of the stage), `Hud` (UiHud, `position = Vector2(0, 590)`), `Banner` (UiBanner, `position = Vector2(24, 4)`), `Toasts` (UiToast, `size = STAGE`), `Tooltip` (UiTooltip), `Fade` (ColorRect, `size = STAGE`, colour `Color(0, 0, 0, 0)`, mouse ignore). Then `layout()`, connect `get_viewport().size_changed` to `layout`, and bind `/root/Game` when it exists: `var g := get_node_or_null("/root/Game"); if g != null and g.get("state") != null: bind_game(g)`. `func layout() -> void`: `var canvas := get_viewport_rect().size`; `$Stage.position = stage_position(canvas)`; compute `safe_insets(Vector2(DisplayServer.window_get_size()), Rect2(DisplayServer.get_display_safe_area()), canvas)` and store `stage_safe = stage_insets(..)` (a public Dictionary var, default all zeros; skip the safe-area call and keep zeros when the window size is zero). Use `get_node("Stage")` instead of `$` if you prefer.''',
   r'''API: `func bind_game(game: Object) -> void`: `game.toast_requested.connect(func(t: String): get_node("Stage/Toasts").show_text(t))`; `get_node("Stage/Hud").bind(game)`. `func show_hud(on: bool) -> void`: `Stage/Hud.visible = on`. `func say(text: String, tail_x: float = -1.0) -> void`: `Stage/Banner.say(text, tail_x)`. `func fade_to(alpha: float, duration: float = 0.25) -> Tween`: if `duration <= 0.0` set `Stage/Fade` `color.a = alpha` immediately and return `null`; else tween the property `color:a` to `alpha` over `duration` and return the Tween. `func scenes() -> SceneHost: return get_node("Stage/Scenes")`.''',
   r'''`godot/tests/test_main.gd`: `test_static_math`: `Main.stage_position(Vector2(1280, 720)) == Vector2.ZERO`; `Main.stage_position(Vector2(1600, 720)) == Vector2(160, 0)`; `Main.stage_position(Vector2(1281, 721)) == Vector2(0, 0)`; `safe_insets(Vector2(2400, 1080), Rect2(400, 0, 1600, 1080), Vector2(1600, 720))` has `left` near 266.667 (eps 0.01) and `right` near 266.667 and `top` 0.0; `stage_insets(that, Vector2(160, 0))` has `left` near 106.667 and `top` 0.0; with insets smaller than the strip (`safe_insets(Vector2(2400,1080), Rect2(100,0,2200,1080), Vector2(1600,720))` then `stage_insets(.., Vector2(160, 0))`) `left` is 0.0. `test_tree`: instantiate `load("res://scenes/main.tscn")`, add to `tree().root`; nodes exist via `get_node_or_null`: `Backdrop`, `Stage`, `Stage/Scenes`, `Stage/Hud`, `Stage/Banner`, `Stage/Toasts`, `Stage/Tooltip`, `Stage/Fade`; `Stage.size == Vector2(1280, 720)`; `Hud.position == Vector2(0, 590)`; `Banner.position == Vector2(24, 4)`; `scenes()` is a SceneHost; `show_hud(false)` hides the HUD, `show_hud(true)` shows it. `test_fade`: `fade_to(0.5, 0.0)`: `Stage/Fade.color.a` near 0.5. `test_bind_fake`: `var g := TestFakeGame.new()`; `m.bind_game(g)`; `g.toast_requested.emit("Hi")`: `Stage/Toasts.texts() == ["Hi"]`; the HUD shows the fake state's day (`Stage/Hud/Calendar.day == g.state.day`). `test_say`: `m.say("hello")`: `Stage/Banner.full_text == "HELLO"`. Free the instance at the end of each test and call `UiCashHistory.reset()` (the auto-bound Game autoload records into the history).''',
   ],
  accept=["`sh tools/godot/gtest.sh test_main` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh scenes/main.tscn /tmp/main.png 8`, then LOOK at /tmp/main.png with the Read tool and describe it in your final reply (expected: a dark screen with the HUD strip along the bottom: four grey plate slots, CASH bar, calendar sheet, white SALES box, REP and BUZZ bars; the banner is empty; nothing overlaps or runs off the screen). Fix what is wrong."]),

 # ------------------------------------------------------------------------------------------------ TV
 dict(id="GDU09", title="TV: CRT shader, CrtMath and test pattern demo", needs=[HARN],
  files=["godot/tv/crt.gdshader", "godot/tv/crt_math.gd", "godot/tv/crt_demo.tscn", "godot/tv/crt_demo.gd", "godot/tests/test_crt.gd"],
  goal="The CRT look: one canvas_item shader (barrel curvature, scanlines, bloom, vignette, noise, flicker, static) plus `CrtMath`, a GDScript twin of the curvature function so touch positions can be mapped through the glass exactly. A demo scene shows the shader on a test pattern.",
  read=[PLAN, TESTS, "docs/GODOT.md section 'The TV is the centre of the game'", "src/art/crt.js (what the JS CRT overlay did)"],
  steps=[
   r'''`godot/tv/crt.gdshader` - write EXACTLY this source (Compatibility-renderer safe):
```
shader_type canvas_item;
uniform float curvature : hint_range(0.0, 0.5) = 0.12;
uniform float scanline_strength : hint_range(0.0, 1.0) = 0.25;
uniform float scanline_count = 224.0;
uniform float bloom : hint_range(0.0, 1.0) = 0.35;
uniform float vignette : hint_range(0.0, 1.0) = 0.35;
uniform float noise_amount : hint_range(0.0, 0.2) = 0.04;
uniform float flicker : hint_range(0.0, 0.1) = 0.02;
uniform float static_amount : hint_range(0.0, 1.0) = 0.0;

vec2 warp(vec2 uv) {
	vec2 cc = uv - vec2(0.5);
	float dist = dot(cc, cc) * curvature;
	return uv + cc * (1.0 + dist) * dist;
}

float hash(vec2 p) {
	return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void fragment() {
	vec2 uv = warp(UV);
	if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
		COLOR = vec4(0.0, 0.0, 0.0, 1.0);
	} else {
		vec3 col = texture(TEXTURE, uv).rgb;
		vec2 px = TEXTURE_PIXEL_SIZE * 1.5;
		vec3 glow = texture(TEXTURE, uv + vec2(px.x, 0.0)).rgb + texture(TEXTURE, uv - vec2(px.x, 0.0)).rgb + texture(TEXTURE, uv + vec2(0.0, px.y)).rgb + texture(TEXTURE, uv - vec2(0.0, px.y)).rgb;
		col += glow * 0.25 * bloom;
		float s = 0.5 + 0.5 * sin(uv.y * scanline_count * 6.28318);
		col *= 1.0 - scanline_strength * (1.0 - s);
		float n = hash(uv * 640.0 + vec2(floor(TIME * 24.0)));
		col += (n - 0.5) * noise_amount;
		col = mix(col, vec3(n), static_amount);
		float v = length((UV - 0.5) * vec2(1.0, 1.1));
		col *= 1.0 - vignette * smoothstep(0.35, 0.8, v);
		col *= 1.0 + flicker * sin(TIME * 60.0);
		COLOR = vec4(col, 1.0);
	}
}
```''',
   r'''`godot/tv/crt_math.gd`: `class_name CrtMath`, `extends RefCounted`, static. `const DEFAULT_CURVATURE := 0.12`. `static func warp(uv: Vector2, curvature: float = DEFAULT_CURVATURE) -> Vector2`: `var cc := uv - Vector2(0.5, 0.5)`; `var dist := cc.dot(cc) * curvature`; `return uv + cc * (1.0 + dist) * dist` (the SAME formula as `warp` in the shader). `static func inside(uv: Vector2) -> bool: return uv.x >= 0.0 and uv.x <= 1.0 and uv.y >= 0.0 and uv.y <= 1.0`. `static func glass_to_source(p: Vector2, glass: Vector2, source: Vector2, curvature: float = DEFAULT_CURVATURE) -> Vector2`: `var w := warp(Vector2(p.x / glass.x, p.y / glass.y), curvature)`; `return Vector2(w.x * source.x, w.y * source.y)` (where on the 640x448 screen a touch at glass position `p` lands).''',
   r'''`godot/tv/crt_demo.gd`: `extends Control`. `_ready()`: `size = Vector2(1280, 720)`; build a `SubViewport` (child, `size = Vector2i(640, 448)`, `render_target_update_mode = SubViewport.UPDATE_ALWAYS`) containing a test pattern made of nodes: a full-size `ColorRect` in `UiTheme.color("blue")`; 8 vertical colour-bar `ColorRect`s of width 80 and height 200 at y = 40 (white, yellow, cyan, green, purple `#6F3D86`, red `#D9483B`, blue `#352879`, black); a 1-px-pitch grid is NOT needed; a `Label` "WEBB TV TEST CARD" at (120, 300) with the project font (use `UiTheme.title_font()` via `add_theme_font_override("font", ...)` and `add_theme_font_size_override("font_size", 24)`), colour white; a `Label` "CH 1" at (20, 8). Then a `TextureRect` named "Glass" at `Vector2(340, 150)` of `size = Vector2(600, 420)`, `texture = viewport.get_texture()`, `stretch_mode = TextureRect.STRETCH_SCALE`, `expand_mode = TextureRect.EXPAND_IGNORE_SIZE`, with a `ShaderMaterial` using `load("res://tv/crt.gdshader")`. A black `ColorRect` backdrop first. `godot/tv/crt_demo.tscn`: text scene with root `[node name="CrtDemo" type="Control"]` and `script = ExtResource("1")` (the script above).''',
   r'''`godot/tests/test_crt.gd`: `test_warp_values`: `CrtMath.warp(Vector2(0.5, 0.5), 0.12) == Vector2(0.5, 0.5)`; `CrtMath.warp(Vector2(1.0, 0.5), 0.12).x` near 1.01545 (eps 1e-6) and `.y` near 0.5; `CrtMath.warp(Vector2(0.3, 0.8), 0.0) == Vector2(0.3, 0.8)` (curvature 0 is the identity); symmetry: `warp(Vector2(0.0, 0.5), 0.12).x` near `-0.01545` (eps 1e-6). `test_inside`: `inside(Vector2(0.5, 0.5))` true, `inside(Vector2(1.01545, 0.5))` false, `inside(Vector2(0, 0))` true. `test_glass_to_source`: `glass_to_source(Vector2(300, 210), Vector2(600, 420), Vector2(640, 448), 0.0) == Vector2(320, 224)`; with the default curvature the centre point still maps to (320, 224) (use `near` on x and y, eps 1e-4); `glass_to_source(Vector2(0, 0), Vector2(600, 420), Vector2(640, 448), 0.0) == Vector2(0, 0)`. `test_shader_loads`: `var sh := load("res://tv/crt.gdshader") as Shader`; not null; `sh.code.contains("uniform float curvature")`, `contains("scanline_strength")`, `contains("static_amount")`, `contains("vec2 warp(vec2 uv)")`. `test_demo_instantiates`: `var d := (load("res://tv/crt_demo.tscn") as PackedScene).instantiate()`; add to `tree().root`; `d.get_node_or_null("Glass") != null`; `(d.get_node("Glass") as TextureRect).material is ShaderMaterial`; free it.'''],
  accept=["`sh tools/godot/gtest.sh test_crt` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh tv/crt_demo.tscn /tmp/crt.png 12`, then LOOK at /tmp/crt.png with the Read tool and describe it (expected: a black screen with a rounded-corner TV picture in the middle showing 8 colour bars, the text WEBB TV TEST CARD, faint horizontal scanlines, darker corners). Say honestly if the picture is all black, all white or has no scanlines, and fix the shader if so."],
  oos=["godot/tv/tv.gd and tv.tscn (GDU10)."]),

 dict(id="GDU27", title="TV: static transition node", needs=[HARN],
  files=["godot/tv/static.gdshader", "godot/tv/tv_static.gd", "godot/tests/test_tv_static.gd"],
  goal="`TvStatic`: the full-screen snow shown between channels. It plays for 0.4 s: intensity ramps up to a peak at the half-way point (signal `midpoint`, where the channel is swapped) and back down (signal `finished`). It blocks taps while playing.",
  read=[PLAN, TESTS, "src/ui/transitions.js (the JS 'static' transition, 400 ms)"],
  steps=[
   r'''`godot/tv/static.gdshader`: `shader_type canvas_item;` with `uniform float intensity : hint_range(0.0, 1.0) = 0.0;` and `fragment()`: `float n = fract(sin(dot(floor(UV * vec2(160.0, 112.0)) + vec2(floor(TIME * 30.0)), vec2(12.9898, 78.233))) * 43758.5453);` `float roll = smoothstep(0.0, 0.08, abs(fract(UV.y - TIME * 0.7) - 0.5) - 0.42);` `vec3 snow = vec3(n * 0.85 + 0.1);` `snow = mix(snow, vec3(0.0), roll * 0.5);` `COLOR = vec4(snow, intensity);` (the node fades in and out by `intensity`).''',
   r'''`godot/tv/tv_static.gd`: `class_name TvStatic`, `extends ColorRect`. Signals `midpoint` and `finished`. Vars `duration: float = 0.4`, `_elapsed: float = 0.0`, `_playing: bool = false`, `_mid_done: bool = false`. `_init`: `size = Vector2(640, 448)`, `color = Color.WHITE`, `visible = false`, `mouse_filter = MOUSE_FILTER_IGNORE`; in `_ready()` assign a `ShaderMaterial` with `load("res://tv/static.gdshader")` to `material`. `static func intensity_at(u: float) -> float: return clampf(1.0 - absf(2.0 * u - 1.0), 0.0, 1.0)` (triangle: 0 at the ends, 1 in the middle). `func play(d: float = 0.4) -> void`: `duration = d`, `_elapsed = 0.0`, `_playing = true`, `_mid_done = false`, `visible = true`, `mouse_filter = MOUSE_FILTER_STOP`, `_apply()`. `func is_playing() -> bool`. `func progress() -> float: return clampf(_elapsed / duration, 0.0, 1.0)`. `func _apply() -> void`: if `material is ShaderMaterial` set shader parameter `intensity` to `intensity_at(progress())`.''',
   r'''`func advance(dt: float) -> void`: if not playing return; `_elapsed += dt`; if not `_mid_done` and `_elapsed >= duration * 0.5`: `_mid_done = true`, `midpoint.emit()`; if `_elapsed >= duration`: `_playing = false`, `visible = false`, `mouse_filter = MOUSE_FILTER_IGNORE`, `finished.emit()`; else `_apply()`. `_process(dt)` calls `advance(dt)`.''',
   r'''`godot/tests/test_tv_static.gd`: `test_intensity`: `TvStatic.intensity_at(0.0)` near 0.0, `(0.25)` near 0.5, `(0.5)` near 1.0, `(0.75)` near 0.5, `(1.0)` near 0.0, `(2.0)` near 0.0. `test_play`: `var s := TvStatic.new()`, connect `midpoint` and `finished` to counters; `s.play(0.5)`: `is_playing()`, `visible`, `mouse_filter == Control.MOUSE_FILTER_STOP`; `advance(0.125)`: progress near 0.25, midpoint 0, finished 0; `advance(0.125)`: midpoint 1; `advance(0.25)`: finished 1, `is_playing()` false, `visible == false`, mouse filter back to IGNORE. `test_one_big_step`: `play(0.4)`, `advance(5.0)` fires midpoint once and finished once, in that order (record the order in an Array of strings: `["midpoint", "finished"]`). `test_idle`: `advance(1.0)` while not playing emits nothing. `test_shader`: `(load("res://tv/static.gdshader") as Shader).code.contains("uniform float intensity")`.'''],
  accept=["`sh tools/godot/gtest.sh test_tv_static` last line is `GDTEST OK`."]),

 dict(id="GDU10", title="TV: tv.tscn cabinet, glass and SubViewport", needs=["GDU01", "GDU09"],
  files=["godot/tv/tv.tscn", "godot/tv/tv.gd", "godot/tests/test_tv.gd"],
  goal="The big Webb TV node, 760x560 px (the centre of the game): a chunky wooden-cabinet CRT drawn in code, a 600x420 glass showing a 640x448 SubViewport through the CRT shader, and exact mapping of touches on the glass into the screen. Remote buttons and channels come in GDU11 and GDU12.",
  read=[PLAN, TESTS, THEME, "godot/tv/crt.gdshader and crt_math.gd (GDU09)", "docs/GODOT.md section 'The TV is the centre of the game'"],
  steps=[
   r'''`godot/tv/tv.tscn` (text scene): `[gd_scene load_steps=2 format=3]`, `[ext_resource type="Script" path="res://tv/tv.gd" id="1"]`, root `[node name="Tv" type="Control"]` with `script = ExtResource("1")`. Children are built in code.''',
   r'''`godot/tv/tv.gd`: `class_name Tv`, `extends Control`. Consts `SIZE := Vector2(760, 560)`, `GLASS := Rect2(60, 50, 600, 420)`, `SCREEN := Vector2(640, 448)`. Signal `closed` (used from GDU12). `_init`: `size = SIZE`, `custom_minimum_size = SIZE`, `mouse_filter = MOUSE_FILTER_PASS`. `_ready()` builds (names exact): `Viewport` (SubViewport: `size = Vector2i(640, 448)`, `render_target_update_mode = SubViewport.UPDATE_ALWAYS`, `transparent_bg = false`, `canvas_item_default_texture_filter = Viewport.DEFAULT_CANVAS_ITEM_TEXTURE_FILTER_NEAREST`, `gui_disable_input = false`); inside it `Screen` (a Control, `size = Vector2(640, 448)`, this is where channels go) with a black `ColorRect` background child; and `Glass` (TextureRect child of the Tv: `position = GLASS.position`, `size = GLASS.size`, `texture = $Viewport.get_texture()`, `expand_mode = TextureRect.EXPAND_IGNORE_SIZE`, `stretch_mode = TextureRect.STRETCH_SCALE`, `mouse_filter = MOUSE_FILTER_STOP`, a `ShaderMaterial` with `crt.gdshader` stored in `var crt_material`). Connect `Glass.gui_input` to `_on_glass_input`.''',
   r'''API: `func host() -> Control: return get_node("Viewport/Screen")`. `var curvature: float = CrtMath.DEFAULT_CURVATURE`. `func glass_to_screen(p: Vector2) -> Vector2: return CrtMath.glass_to_source(p, GLASS.size, SCREEN, curvature)`. `func set_crt(on: bool) -> void`: `Glass.material = crt_material if on else null`; when on set shader parameter `curvature` to `curvature`; `func crt_on() -> bool`. `func convert_event(ev: InputEvent) -> InputEvent`: for `InputEventMouseButton` or `InputEventMouseMotion` return a duplicate whose `position` (and `global_position`) is `glass_to_screen(ev.position)`; any other event returns `null`. `func _on_glass_input(ev: InputEvent) -> void`: `var c := convert_event(ev)`; if not null `$Viewport.push_input(c, true)`.''',
   r'''`_draw()` (cabinet, local coordinates, in this order): (1) `UiTheme.draw_box(self, Rect2(0, 0, 760, 560), UiTheme.color("woodDark"), UiTheme.color("ink"), 4, false)`; (2) wood grain: for `y` from 12 to 548 step 16: `draw_rect(Rect2(8, y, 744, 2), UiTheme.color("woodDark").lightened(0.08))`; (3) bezel `UiTheme.draw_box(self, Rect2(36, 30, 688, 448), Color("#2A2530"), UiTheme.color("ink"), 4, false)`; (4) glass recess `draw_rect(Rect2(56, 46, 608, 428), Color.BLACK)`; (5) control plate `UiTheme.draw_box(self, Rect2(36, 478, 688, 74), UiTheme.color("woodLight"), UiTheme.color("ink"), 4, false)`; (6) two knobs: for `cx` in `[668.0, 700.0]`: `draw_circle(Vector2(cx, 516), 14.0, Color.BLACK)` and `draw_arc(Vector2(cx, 516), 14.0, 0.0, TAU, 24, UiTheme.color("lightgrey"), 2.0)`; (7) brand plate `UiTheme.draw_box(self, Rect2(52, 492, 80, 40), UiTheme.color("brass"), UiTheme.color("ink"), 4, false)` with "WEBB" (role "h3", colour "ink") at (60, 504). The cabinet is drawn UNDER the children (the glass is a child), which is the default.''',
   r'''`godot/tests/test_tv.gd`: `test_size_and_tree`: `var tv := (load("res://tv/tv.tscn") as PackedScene).instantiate()`; add to `tree().root`; `tv.size == Vector2(760, 560)`; `Tv.GLASS == Rect2(60, 50, 600, 420)`; nodes `Viewport`, `Viewport/Screen`, `Glass` exist; `(tv.get_node("Viewport") as SubViewport).size == Vector2i(640, 448)`; `tv.host().size == Vector2(640, 448)`; `(tv.get_node("Glass") as TextureRect).texture != null`; the glass aspect equals the screen aspect: `near(600.0 / 420.0, 640.0 / 448.0, 1e-9)`. `test_crt_toggle`: `tv.crt_on()` true after `_ready`; `set_crt(false)`: `Glass.material == null` and `crt_on()` false; `set_crt(true)`: the material is a ShaderMaterial. `test_mapping`: `tv.curvature = 0.0`: `glass_to_screen(Vector2(300, 210)) == Vector2(320, 224)`, `glass_to_screen(Vector2(600, 420)) == Vector2(640, 448)`; with the default curvature the centre maps to (320, 224) (near, eps 1e-3) and `glass_to_screen(Vector2(0, 210)).x < 0.0` (the warp pushes the edge outside). `test_convert_event`: with `curvature = 0.0` an `InputEventMouseButton` at (150, 105) converts to position (160, 112) and the original event is untouched (still (150, 105)); a `InputEventMouseMotion` converts too; an `InputEventKey` gives `null`. Free `tv` at the end of each test.'''],
  accept=["`sh tools/godot/gtest.sh test_tv` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh tv/tv.tscn /tmp/tv.png 10`, then LOOK at /tmp/tv.png with the Read tool and describe it (expected, in the top-left of the window because the node is not centred yet: a brown wooden CRT cabinet with a dark bezel, a black glass area with rounded CRT corner darkening, a lighter control plate along the bottom with two round knobs on the right and a brass WEBB plate on the left)."],
  oos=["Remote buttons (GDU11), channels and static node wiring (GDU12)."]),

 dict(id="GDU11", title="TV: remote control buttons (CH-, CH+, OK, BACK)", needs=["GDU10", "GDU02"],
  files=["godot/tv/tv_remote.gd", "godot/tv/tv.gd", "godot/tests/test_tv_remote.gd"],
  goal="`TvRemote`: the four big buttons on the TV's control plate (CH-, CH+, OK, BACK, each 96x64) plus keyboard shortcuts, wired into the Tv as the signal `remote(action)`.",
  read=[PLAN, TESTS, BTN, "godot/tv/tv.gd (GDU10)"],
  steps=[
   r'''`godot/tv/tv_remote.gd`: `class_name TvRemote`, `extends Control`. Signals `action(name: String)`. `_init`: `size = Vector2(456, 64)`, `mouse_filter = MOUSE_FILTER_PASS`. `const ACTIONS: Array[String] = ["ch_prev", "ch_next", "ok", "back"]`, `const LABELS: Array[String] = ["CH-", "CH+", "OK", "BACK"]`, `const NODE_NAMES: Array[String] = ["ChPrev", "ChNext", "Ok", "Back"]`. `_ready()` creates four `UiButton`s named by `NODE_NAMES`, `kind = "remote"`, `text = LABELS[i]`, `position = Vector2(i * 120, 0)`, `size = Vector2(96, 64)`, and connects each `activated` to `func(): press_action(ACTIONS[i])` (capture `i` in a local first: `var a: String = ACTIONS[i]`). `func press_action(a: String) -> void: action.emit(a)`. `static func key_to_action(keycode: int) -> String`: KEY_LEFT -> "ch_prev", KEY_RIGHT -> "ch_next", KEY_ENTER / KEY_KP_ENTER / KEY_SPACE -> "ok", KEY_ESCAPE / KEY_BACKSPACE -> "back", anything else "". `func _unhandled_key_input(event: InputEvent) -> void`: for a pressed, non-echo `InputEventKey` with a non-empty action: `press_action(a)` and `get_viewport().set_input_as_handled()`.''',
   r'''Edit `godot/tv/tv.gd` (GDU10): add `signal remote(action: String)`; in `_ready()` after the glass: `var r := TvRemote.new()`, `r.name = "Remote"`, `r.position = Vector2(152, 484)`, `add_child(r)`, `r.action.connect(func(a: String): remote.emit(a))`. Do not change anything else in that file.''',
   r'''`godot/tests/test_tv_remote.gd`: `test_keys`: `TvRemote.key_to_action(KEY_LEFT) == "ch_prev"`, `KEY_RIGHT` "ch_next", `KEY_ENTER` "ok", `KEY_KP_ENTER` "ok", `KEY_SPACE` "ok", `KEY_ESCAPE` "back", `KEY_BACKSPACE` "back", `KEY_A` "". `test_buttons`: `var r := TvRemote.new()` added to the tree; for the four names the node exists, is a `UiButton`, has `size == Vector2(96, 64)` (height >= 64) and `position.x == i * 120.0`; texts are "CH-", "CH+", "OK", "BACK"; `kind == "remote"`; collect `action`; press+release inside `Ok` (mouse events at (10, 10) via the button's `handle_event`) gives `["ok"]`; the same on `Back` adds "back"; `press_action("ch_next")` adds "ch_next". `test_in_tv`: instantiate `res://tv/tv.tscn`, add to the tree: `Remote` exists at `Vector2(152, 484)`; `Remote.position.y + Remote.size.y <= 560.0`; collect the Tv `remote` signal; tap `Remote/ChNext` (press and release inside): the Tv emitted `["ch_next"]`. Free nodes at the end of each test.'''],
  accept=["`sh tools/godot/gtest.sh test_tv_remote` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh tv/tv.tscn /tmp/tv_remote.png 10`, LOOK at /tmp/tv_remote.png and describe it (expected: the four dark remote buttons CH-, CH+, OK, BACK in a row on the wooden control plate, readable cream text, none touching the knobs or the brand plate)."]),

 dict(id="GDU28", title="Test helpers: TestFakeGame and channel_shot", needs=[HARN],
  files=["godot/tests/fake_game.gd", "godot/tests/shots/channel_shot.gd", "godot/tests/test_fake_game.gd"],
  goal="`TestFakeGame` stands in for the `Game` autoload in channel and widget tests (same `state` shape, `act()`, signals), and `channel_shot.gd` is the generic script for channel screenshot scenes.",
  read=[PLAN, TESTS, "godot/autoload/game.gd (GDF10: `act` returns `{ok, msg}`; on `ok == false` with a message it emits `toast_requested(msg)` itself; on success it emits `changed`)", "src/core/state.js and src/sim/newgame.js (the real state keys, camelCase like `garageSlots`)"],
  steps=[
   r'''`godot/tests/fake_game.gd`: `class_name TestFakeGame`, `extends RefCounted`. Signals `changed`, `toast_requested(text: String)`, `day_advanced`, `game_over`. Vars `state: Dictionary`, `acts: Array = []` (each `{"action": String, "params": Dictionary}`), `toasts: Array[String] = []`, `next_result: Dictionary = {"ok": true, "msg": "Done"}`. `_init()`: `state = TestFakeGame.sample_state()` and `toast_requested.connect(func(t: String): toasts.append(t))`. `func act(action: String, params: Dictionary = {}) -> Dictionary`: append to `acts`; `var r := next_result.duplicate(true)`; if `r.get("ok", false) == false and str(r.get("msg", "")) != ""` emit `toast_requested(r.msg)` (like the real Game); if `r.ok == true` emit `changed`; return `r`.''',
   r'''`static func sample_state() -> Dictionary` returns EXACTLY this data (keys camelCase like the real state): `day 12`, `cash 12345`, `reputation 40`, `buzz 10`, `garageSlots 3`, `nextId 20`, `market {"priceMult": 1}`; `cars`: two Dictionaries `{"id": "c1", "modelId": "t1_allergy", "owned": true, "owner": null, "rentMonthly": 0, "paid": 3500, "condition": 6.0, "fault": null, "lastServiceDay": 1, "jobsDone": 0, "boughtDay": 1, "impoundedUntil": 0, "rentedAtCondition": null}` and `{"id": "c2", "modelId": "t1_robbin", ... "condition": 9.0, "fault": {"faultId": "puncture", "label": "Flat tyre", "cost": 80, "severity": "minor"} ...}` (same keys as c1 otherwise); `shop`: `{"listings": [...], "refreshedDay": 10}` with three listings `{"listingId": "L1", "modelId": "t1_chimp", "mode": "sale", "price": 4000, "condition": 7.0, "owner": null}`, `{"listingId": "L2", "modelId": "t1_maurice", "mode": "rent", "price": 240, "condition": 5.5, "owner": "Old Mrs Pym"}`, `{"listingId": "L3", "modelId": "t1_cooker", "mode": "sale", "price": 5200, "condition": 8.0, "owner": null}`; `requests`: `{"id": "Q1", "jobTypeId": "wedding", "customer": "Mrs Pym", "fee": 900, "minDesirability": 3, "minReliability": 3, "minCondition": 6, "expiresDay": 14, "blurb": "Mrs Pym needs something posh."}` and `{"id": "Q2", "jobTypeId": "wedding", "customer": "Mr Trent", "fee": 700, "minDesirability": 9, "minReliability": 3, "minCondition": 6, "expiresDay": 13, "blurb": "Mr Trent wants a grand arrival."}`; `stats {"jobsDone": 2, "jobsFailed": 1, "adsRun": 3, "carsBought": 1, "carsSold": 0, "bestAuctionSale": 0, "faults": 1}`; `plates {"fatcat": false, "stable": false, "household": false, "hammer": false}`; `headlines ["Local vicar buys round of tea", "Pigeon wins raffle"]`; `today {"day": 12, "headline": "Local vicar buys round of tea", "events": ["Bought nothing. Lovely.", "Dave found a spanner."], "monthReport": null}`; `flags {"gameOver": false, "won": false, "reason": ""}`; `auction {"month": 1, "lots": [], "consigned": [], "lastResults": []}`; `pending []`; `sit []`; `log []`. Use `null` for JSON null.''',
   r'''`godot/tests/shots/channel_shot.gd`: `extends Control`. `var _game: TestFakeGame`. `_ready()`: add a full-rect `ColorRect` colour `Color("#14102A")` as first child; `_game = TestFakeGame.new()`; `var ps := load(str(get_meta("channel"))) as PackedScene`; `var ch := ps.instantiate()`; `ch.position = Vector2(320, 136)`; `add_child(ch)`; `ch.enter(_game)`; then for each entry `c` of `get_meta("calls", [])` (an Array of `[method_name, args_array]`): `ch.callv(c[0], c[1])`. (`size = Vector2(1280, 720)` at the top.) The channel cards each add a tiny scene that sets the meta `channel` (and optionally `calls`).''',
   r'''`godot/tests/test_fake_game.gd`: `test_sample_state`: `var g := TestFakeGame.new()`; `g.state.cash == 12345`, `g.state.day == 12`, `g.state.cars.size() == 2`, `g.state.cars[1].fault.label == "Flat tyre"`, `g.state.cars[0].fault == null`, `g.state.shop.listings.size() == 3`, `g.state.shop.listings[1].mode == "rent"`, `g.state.requests.size() == 2`, `g.state.today.monthReport == null`, `g.state.plates.fatcat == false`; every model id used exists: `Data.car_by_id(id) != {}` for t1_allergy, t1_robbin, t1_chimp, t1_maurice, t1_cooker, and `Data.job_type_by_id("wedding") != {}`. `test_act_records`: `g.act("buy_car", {"listing_id": "L1"})` returns `{"ok": true, "msg": "Done"}`; `g.acts == [{"action": "buy_car", "params": {"listing_id": "L1"}}]`; a collected `changed` count is 1. `test_act_failure`: `g.next_result = {"ok": false, "msg": "No way"}`; `act("x")` returns it; `g.toasts == ["No way"]`; `changed` count stays 0. `test_independent`: two `TestFakeGame` instances do not share `state` (change cash in one).'''],
  accept=["`sh tools/godot/gtest.sh test_fake_game` last line is `GDTEST OK`."]),

 dict(id="GDU12", title="TV: ChannelBase, ChannelManager and TV wiring", needs=["GDU11", "GDU27", "GDU28", "GDU01", "GDU31", DATA, FMT],
  files=["godot/tv/channel_base.gd", "godot/tv/channel_manager.gd", "godot/tv/tv.gd", "godot/tests/test_channels.gd", "godot/tests/shots/tv_shot.tscn", "godot/tests/shots/tv_shot.gd"],
  goal="The channel contract and its manager: `ChannelBase` (what every channel scene extends: `enter(game)`, `leave()`, signal `done`, `refresh()`, `_paint()`), `ChannelManager` (registry, tune / step with the static transition, OK and BACK routing) and the Tv wiring: remote -> manager, manager -> Tv `closed`, channel name on screen.",
  read=[PLAN, TESTS, THEME, "godot/tv/tv.gd, tv_remote.gd, tv_static.gd (GDU10, GDU11, GDU27)", FAKE, "docs/GODOT.md ('A channel is a scene res://tv/<name>_channel.tscn ... enter(game), leave(), signal done')"],
  steps=[
   r'''`godot/tv/channel_base.gd`: `class_name ChannelBase`, `extends Control`. Signal `done`. `const MIN_TOUCH := 72`. Vars `game: Object = null`, `title: String = "NO SIGNAL"`, `placeholder: bool = false`. `static var _models: Dictionary = {}`. `_init`: `size = Vector2(640, 448)`, `custom_minimum_size = Vector2(640, 448)`, `mouse_filter = MOUSE_FILTER_STOP`, `clip_contents = true`. Contract: `func enter(g: Object) -> void`: `game = g`; connect `g.changed` to `_on_game_changed` (only if not yet connected); `_on_enter()`; `refresh()`; `queue_redraw()`. `func leave() -> void`: disconnect `changed` if connected; `_on_leave()`; `game = null`. Hooks to override (empty here): `func _on_enter() -> void`, `func _on_leave() -> void`, `func refresh() -> void`, `func _paint() -> void`, `func on_ok() -> void`, `func on_back() -> bool: return false` (true = handled, the manager does not leave the TV). `func _on_game_changed() -> void: refresh(); queue_redraw()`. `func state() -> Dictionary: return game.state if game != null else {}`. `func toast(text: String) -> void: if game != null: game.toast_requested.emit(text)`.''',
   r'''Drawing: `func _draw() -> void`: fill `Rect2(Vector2.ZERO, size)` with `UiTheme.color("blue")`; header bar `Rect2(0, 0, 640, 40)` in `UiTheme.color("night")` with a 2 px "lightblue" line at its bottom; the title `UiTheme.draw_text(self, title, Vector2(12, 12), "h3", UiTheme.color("phosphor"))` and, right-aligned in the header, `"DAY %d" % int(state().get("day", 1))` (role "caption", colour "cream", `width = 628`, `align = HORIZONTAL_ALIGNMENT_RIGHT`); when `placeholder` also draw "NO SIGNAL" centred (role "h2", colour "white") at y 200; then `_paint()`. Static helpers: `static func models_by_id() -> Dictionary`: build once from `Data.cars()` (id -> model); `static func reset_cache() -> void: _models = {}`; `static func model_of(id: String) -> Dictionary` (`{}` if unknown); `static func paint_of(id: String) -> Color: return Color(Data.paint_of(id))`; `static func job_name(id: String) -> String`: `Data.job_type_by_id(id).get("name", id.to_upper())`.''',
   r'''`godot/tv/channel_manager.gd`: `class_name ChannelManager`, `extends Node`. Signals `tuned(id: String, title: String, index: int)` and `exit_requested`. `const DEFAULTS: Array = [{"id": "shop", "title": "SHOP", "scene": "res://tv/shop_channel.tscn"}, {"id": "news", "title": "NEWS", "scene": "res://tv/news_channel.tscn"}, {"id": "adverts", "title": "ADVERTS", "scene": "res://tv/adverts_channel.tscn"}, {"id": "ledger", "title": "LEDGER", "scene": "res://tv/ledger_channel.tscn"}, {"id": "bookings", "title": "BOOKINGS", "scene": "res://tv/bookings_channel.tscn"}]`. Vars `channels: Array = DEFAULTS.duplicate(true)`, `host: Control`, `game: Object`, `fx: TvStatic`, `_current: ChannelBase`, `_index: int = -1`, `_pending: int = -1`. `func setup(h: Control, g: Object, f: TvStatic = null) -> void`: store; if `f != null` connect `f.midpoint` to `_on_midpoint` and `f.finished` to `_on_finished`. `func register(id: String, title: String, scene: String) -> void` (replace the entry with that id or append). `func index_of(id: String) -> int` (-1 unknown). `func current_id() -> String` (`""` when none). `func current() -> ChannelBase`. `func current_index() -> int`.''',
   r'''Tuning: `func tune(id: String) -> bool`: `var i := index_of(id)`; unknown -> false. `return _request(i)`. `func step(dir: int) -> void`: `var n := channels.size()`; if `n == 0` return; target = `0 if _index < 0 and dir > 0`, `n - 1 if _index < 0 and dir < 0`, else `posmod(_index + dir, n)`; `_request(target)`. `func _request(i: int) -> bool`: if `fx != null and fx.is_playing()` { `_pending = i`; return true }; if `i == _index` return true; if `fx == null or _current == null` { `_swap(i)`; return true }; `_pending = i`; `fx.play(0.4)`; return true. `func _on_midpoint() -> void: if _pending >= 0: var i := _pending; _pending = -1; _swap(i)`. `func _on_finished() -> void: if _pending >= 0: var i := _pending; _pending = -1; _request(i)` (a tune made AFTER the midpoint starts a fresh transition once the first one ends; at that moment the static is no longer playing). `func _swap(i: int) -> void`: if `_current != null`: `_current.leave()`, `host.remove_child(_current)`, `_current.queue_free()`. Then `var entry: Dictionary = channels[i]`; the new channel: if `ResourceLoader.exists(entry.scene)` then `(load(entry.scene) as PackedScene).instantiate() as ChannelBase` else null; when null make `ChannelBase.new()` with `placeholder = true` and `title = entry.title`. `host.add_child(ch)`, `host.move_child(ch, 1)` (index 0 is the black background, the static overlay stays last), `ch.done.connect(func(): exit_requested.emit())`, `_current = ch`, `_index = i`, `ch.enter(game)`, `tuned.emit(entry.id, entry.title, i)`.''',
   r'''Buttons: `func ok() -> void: if _current != null: _current.on_ok()`. `func back() -> bool`: if `_current != null and _current.on_back()` return true; `exit_requested.emit()`; return false. `func stop() -> void`: leave and free the current channel (`_index = -1`).''',
   r'''Edit `godot/tv/tv.gd` (GDU10/GDU11): add `var channels: ChannelManager`, `var static_fx: TvStatic`, `var osd: Label`, `var _osd_left: float`. `func setup(game: Object) -> void` (call after the node is in the tree): create `static_fx = TvStatic.new()` named "Static" as the LAST child of `Viewport` (so it is on top); create `channels = ChannelManager.new()` named "Channels" as a child of the Tv; `channels.setup(host(), game, static_fx)`; connect `remote` to `_on_remote`; `channels.exit_requested.connect(func(): closed.emit())`; `channels.tuned.connect(_on_tuned)`; create the OSD `Label` named "Osd" as a child of `Viewport` AFTER `Static`, `position = Vector2(24, 20)`, `add_theme_font_override("font", UiTheme.title_font())`, `add_theme_font_size_override("font_size", 24)`, `add_theme_color_override("font_color", UiTheme.color("phosphor"))`, `visible = false`, `mouse_filter = Control.MOUSE_FILTER_IGNORE`. `func _on_remote(a: String) -> void`: "ch_next" -> `channels.step(1)`; "ch_prev" -> `channels.step(-1)`; "ok" -> `channels.ok()`; "back" -> `channels.back()`. `func _on_tuned(id: String, title: String, index: int) -> void`: `osd.text = "CH %d  %s" % [index + 1, title]`, `osd.visible = true`, `_osd_left = 2.0`. `func tune(id: String) -> bool: return channels.tune(id)`. `func _process(delta: float) -> void`: when `_osd_left > 0.0`: subtract delta and hide the OSD at 0. `tune`/`setup` must not run before `_ready`.''',
   r'''`godot/tests/shots/tv_shot.gd`: `extends Control`; `_ready()`: black backdrop; `var tv := (load("res://tv/tv.tscn") as PackedScene).instantiate()`; `tv.position = Vector2(260, 40)`; `add_child(tv)`; `tv.setup(TestFakeGame.new())`; `tv.tune("shop")`. `godot/tests/shots/tv_shot.tscn`: a text scene with root `Control` named "TvShot" and that script (layout full rect like the channel shot scenes).''',
   r'''`godot/tests/test_channels.gd`: `test_base_contract`: `var c := ChannelBase.new()`; `size == Vector2(640, 448)`; `c.on_back() == false`; with a `TestFakeGame` `g`: `c.enter(g)` stores `game`; `g.changed.is_connected(c._on_game_changed)`; `c.leave()`: `game == null` and the signal is disconnected; `toast("x")` before enter does nothing, after enter `g.toasts == ["x"]`. `test_state_helper`: `enter(g)` then `c.state().day == 12`. `test_model_helpers`: `ChannelBase.model_of("t1_allergy").name == "Austen Allergy"`; `model_of("zzz") == {}`; `ChannelBase.paint_of("t1_robbin") == Color("#C9A227")`; `ChannelBase.job_name("wedding") == "Wedding"`; `ChannelBase.job_name("zzz") == "ZZZ"`. `test_manager_basic` (no static): host `Control` with a black first child, `ChannelManager.new()` `m`, `m.channels = [{"id": "a", "title": "A", "scene": "res://nope_a.tscn"}, {"id": "b", "title": "B", "scene": "res://nope_b.tscn"}, {"id": "c", "title": "C", "scene": "res://nope_c.tscn"}]`; `m.setup(host, TestFakeGame.new(), null)`; collect `tuned`; `m.tune("a")` is true: `current_id() == "a"`, `host.get_child_count() == 2`, `current().placeholder`, `current().title == "A"`; `m.step(1)`: "b"; `m.step(1)`: "c"; `m.step(1)`: "a" (wraps); `m.step(-1)`: "c"; `m.tune("zzz")` false; `tuned` ids recorded `["a", "b", "c", "a", "c"]`; old channels are queued for deletion (`host.get_child_count() == 2` after the loop still); `m.back()` returns false and emits `exit_requested` once. A fresh manager with no channel yet: `step(-1)` tunes the LAST channel. `test_manager_static`: a manager with a real `TvStatic` `fx`: `tune("a")` is immediate (nothing was on); `tune("b")`: still `current_id() == "a"`, `fx.is_playing()`; `fx.advance(0.1)`: still "a"; `fx.advance(0.15)` (total 0.25 >= 0.2): `current_id() == "b"`; `fx.advance(1.0)`: finished; then (second step) `tune("c")` while the static is still in its second half: `current_id()` stays "b"; `fx.advance(1.0)` finishes the first transition and starts a new one (`fx.is_playing()` true, `current_id()` still "b"); `fx.advance(0.25)` -> `current_id() == "c"`. `test_default_registry`: `ChannelManager.DEFAULTS` has the ids `shop, news, adverts, ledger, bookings` in this order and `index_of("ledger") == 3`. `test_tv_wiring`: instantiate `res://tv/tv.tscn`, add to the tree, `tv.setup(TestFakeGame.new())`; `tv.tune("news")` is true; `tv.channels.current_id() == "news"`; `tv.get_node("Viewport/Static")` exists and is the last child of `Viewport`; `tv.get_node("Viewport/Osd").text == "CH 2  NEWS"`; tapping `Remote/ChNext` (press+release inside) leaves the manager on "adverts" after `static_fx.advance(1.0)`; tapping `Remote/Back` makes the Tv emit `closed` once (collect it). Free every node at the end of each test.'''],
  accept=["`sh tools/godot/gtest.sh test_channels` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh tests/shots/tv_shot.tscn /tmp/tv_shot.png 30`, then LOOK at /tmp/tv_shot.png and describe it (expected: the wooden TV in the middle of a black 1280x720 window; on the glass a blue channel screen with the title SHOP or NO SIGNAL in a dark header strip, a green CH 1 SHOP text at the top-left of the glass; scanlines visible)."]),

 # ------------------------------------------------------------------------------------------------ SHOP channel
 dict(id="GDU13", title="Channel SHOP: cars list and details", needs=["GDU12", "GDU18", "GDU19", "GDU02", "GDU31", DATA, FMT],
  files=["godot/tv/shop_channel.gd", "godot/tv/shop_channel.tscn", "godot/tests/shots/shop_shot.tscn", "godot/tests/test_shop_channel.gd"],
  goal="The SHOP channel (port of src/ui/scenes/tvshop.js, display half): the week's telly listings in a scrolling list on the left, the selected car with portrait, quip and STYLE / UPKEEP / GRIT / CONDITION bars on the right. Buying comes in GDU23.",
  read=[PLAN, TESTS, CB, LSTW, "godot/ui/car_portrait.gd (GDU19)", THEME, UTXT, "src/ui/scenes/tvshop.js (read it all: row layout, detail panel, stat bars)", FAKE, CHAN],
  steps=[
   ch_tscn("shop"),
   r'''`godot/tv/shop_channel.gd`: `class_name ShopChannel`, `extends ChannelBase`. `_init`: `super()`; `title = "SHOP"`. Layout consts (channel px): `LIST := Rect2(8, 48, 300, 320)`, `DETAIL := Rect2(316, 48, 316, 320)`. `_ready()` creates `List` (a `UiList`, position/size from `LIST`, `row_h = 72`, `row_painter = _paint_row`) and `Portrait` (a `CarPortrait` at `DETAIL.position`, `size = Vector2(316, 150)`); `List.row_tapped.connect(_on_row)`; `func _on_row(i: int) -> void: _show_selected()`. `func listings() -> Array: return state().get("shop", {}).get("listings", [])`. `func selected_listing() -> Dictionary`: `listings()[List.selected]` when `List.selected` is a valid index, else `{}`. `func refresh() -> void`: `List.set_count(listings().size())`; if `List.selected < 0 and listings().size() > 0` then `List.select(0)`; `_show_selected()`; `queue_redraw()`.''',
   r'''`static func wear_for(condition: float) -> int: return CarPortrait.wear_for(condition)`. `func _show_selected() -> void`: `var l := selected_listing()`; `Portrait.clear()` when empty, else `Portrait.set_car(l.modelId, ChannelBase.paint_of(l.modelId), wear_for(float(l.condition)))`; `queue_redraw()`. Row painter `func _paint_row(list: Control, i: int, r: Rect2, sel: bool) -> void` (draws on `list`): `var l: Dictionary = listings()[i]`; `var m := ChannelBase.model_of(l.modelId)`; box `UiTheme.draw_box(list, r.grow(-2), UiTheme.color("paper"), UiTheme.color("ink"), 4, false)`; line 1 name `UiText.ellipsize(m.get("name", l.modelId), 20)` (role "caption", colour "ink") at `r.position + Vector2(14, 8)`; line 2 at `r.position + Vector2(14, 42)`: the tag `"FOR SALE"` / `"TO RENT"` (role "h3", colour "good" for sale, "warn" for rent); price right-aligned at the row's right edge minus 14: `CoreFormat.money(l.price)` plus `"/mo"` for rent (role "caption", colour "ink"; `draw_text(list, text, pos, role, col, width, HORIZONTAL_ALIGNMENT_RIGHT)` with `pos.x = r.position.x` and `width = r.size.x - 14`); when `sel` a 4 px "lamp" outline just inside the row and an `">"` (role "h3") at `r.position + Vector2(2, 24)`.''',
   r'''`_paint()` (detail side, in channel coordinates): `var l := selected_listing()`. Empty list: `UiTheme.draw_text(self, "Nothing on the telly.", Vector2(8, 200), "body", cream, 624, CENTER)` and a second line "Try again next week." at y 232. Otherwise: `var m := ChannelBase.model_of(l.modelId)`; name `UiText.ellipsize(str(m.get("name", "")).to_upper(), 19)` at `(DETAIL.x, 204)` role "h3" colour "phosphor"; then up to 3 lines at x = DETAIL.x, y = 226, 250, 274 (pitch 24, role "caption", colour "white"): `UiText.wrap("%d. %s" % [m.year, m.quip], 29, 2)` and, for a rent listing, `"Owner: " + l.owner` ellipsized to 29 as the next line. Stat rows at y = 304 + k*16... use pitch 16: STYLE `m.desirability` colour "good", UPKEEP `m.maintenance` "warn", GRIT `m.reliability` "cyan", CONDITION `l.condition` "cyan"; each row: label (role "caption", colour "cream") at `(DETAIL.x, y - 4)`, a bar `UiTheme.draw_bar(self, Rect2(DETAIL.x + 120, y, 190, 12), value / 10.0, col)`; rows at y = 298, 316, 334, 352 (CONDITION's label text is `"COND " + CoreFormat.one_dp(l.condition)`).''',
   shot_scene("shop"),
   r'''`godot/tests/test_shop_channel.gd`: load `res://tv/shop_channel.tscn`, instantiate `c`, add to `tree().root`, `var g := TestFakeGame.new()`, `c.enter(g)`. `test_enter`: `c.get_node("List").count == 3`; `get_node("List").selected == 0`; `get_node("Portrait").get_car_id() == "t1_chimp"`; `selected_listing().listingId == "L1"`; `c.title == "SHOP"`. `test_select`: `get_node("List").select(1, true)`: `selected_listing().listingId == "L2"` and the portrait id is "t1_maurice" and wear is `ShopChannel.wear_for(5.5)` (= 1). `test_empty`: set `g.state.shop.listings = []` then `g.changed.emit()`: list count 0, `selected_listing() == {}`, portrait id "". `test_changed_refreshes`: change `g.state.shop.listings` to just L3 and emit `changed`: list count 1, selected clamps to 0, portrait "t1_cooker". `test_row_painter`: `c.get_node("List").row_painter.is_valid()`. `test_leave`: `c.leave()` disconnects (no error when `g.changed.emit()` follows). Free `c` at the end of each test.'''],
  accept=["`sh tools/godot/gtest.sh test_shop_channel` last line is `GDTEST OK`.", shot("shop")],
  oos=["BUY / RENT buttons (GDU23)."]),

 dict(id="GDU23", title="Channel SHOP: buy and rent actions", needs=["GDU13"],
  files=["godot/tv/shop_channel.gd", "godot/tests/test_shop_actions.gd"],
  goal="Add BUY and RENT to the SHOP channel: two 72 px buttons that call `game.act('buy_car' / 'rent_car')`, with a refusal explained by a toast BEFORE any action is sent (same order as tvshop.js), and OK on the remote buying or renting the selected car.",
  read=[PLAN, TESTS, CB, "godot/tv/shop_channel.gd (GDU13)", BTN, FAKE, "src/ui/scenes/tvshop.js (buyRefusal, rentRefusal, actBuy, actRent) and src/sim/actions.js (buyCar / rentCar messages)", "godot/autoload/game.gd (GDF10: failed actions are toasted by Game itself; do NOT toast a failed result again)"],
  steps=[
   r'''Edit `godot/tv/shop_channel.gd`. Add `static func refusal(st: Dictionary, listing: Dictionary, mode: String) -> String` (`""` means fine), checked in this order: (1) `listing.is_empty()` or `listing.get("mode", "") != mode` -> `"That one is not for sale"` when `mode == "sale"` else `"That one is not for rent"`; (2) `st.cars.size() >= int(st.garageSlots)` -> `"No free garage slot"`; (3) `float(st.cash) < float(listing.price)` -> `"Not enough money"`; else `""`.''',
   r'''In `_ready()` add two `UiButton`s: `BuyBtn` (`text = "BUY"`, `kind = "primary"`) at `Vector2(316, 376)` size `Vector2(150, 72)` and `RentBtn` (`text = "RENT"`) at `Vector2(482, 376)` size `Vector2(150, 72)`. Connect `activated` AND `blocked` of each to `_do_buy` / `_do_rent`. Add `func _do_buy() -> void: _do("sale")` and `func _do_rent() -> void: _do("rent")`. `func _do(mode: String) -> void`: `var l := selected_listing()`; `var why := ShopChannel.refusal(state(), l, mode)`; if `why != ""`: `toast(why)` and return; `var res: Dictionary = game.act("buy_car" if mode == "sale" else "rent_car", {"listing_id": l.listingId})`; if `res.get("ok", false)`: `toast(str(res.get("msg", "")))` (a failure is already toasted by Game). `func on_ok() -> void`: `var l := selected_listing()`; `if l.is_empty(): return`; `_do(str(l.mode))`.''',
   r'''In `refresh()` (after the existing lines) set the enabled flags so the buttons grey out like the JS: `var l := selected_listing()`; `BuyBtn.enabled = ShopChannel.refusal(state(), l, "sale") == ""`; `RentBtn.enabled = ShopChannel.refusal(state(), l, "rent") == ""`. Disabled buttons still emit `blocked` on tap, which runs the same `_do` and so explains the refusal with a toast.''',
   r'''`godot/tests/test_shop_actions.gd` (channel `c` from `res://tv/shop_channel.tscn` entered with a `TestFakeGame` `g`; helper `_tap(btn)` presses at (10, 10) and releases at (12, 12) through `btn.handle_event`). `test_refusal`: with `g.state`: L1 sale price 4000, cash 12345, 2 cars of 3 slots: `ShopChannel.refusal(st, L1, "sale") == ""`; `refusal(st, L1, "rent") == "That one is not for rent"`; `refusal(st, L2, "sale") == "That one is not for sale"`; `refusal(st, {}, "sale") == "That one is not for sale"`; with `st.cash = 100`: `"Not enough money"`; with `st.cars` holding 3 cars (append a copy of c1): `"No free garage slot"` (checked BEFORE money: set cash 100 as well and still expect the slot message). `test_buy`: selected L1; `_tap(c.get_node("BuyBtn"))`: `g.acts == [{"action": "buy_car", "params": {"listing_id": "L1"}}]`; the success text (`"Done"` from the fake) is in `g.toasts`. `test_rent_selected_buy_refused`: `get_node("List").select(1, true)` (L2 is for rent): `_tap(BuyBtn)`: `g.acts` is empty and `g.toasts == ["That one is not for sale"]`; then `_tap(RentBtn)`: act `rent_car` with `listing_id` "L2". `test_failure_not_toasted_twice`: `g.next_result = {"ok": false, "msg": "No way"}`; `_tap(BuyBtn)`: `g.toasts == ["No way"]` (exactly once: the fake toasts failures like the real Game and the channel adds nothing). `test_enabled_flags`: initially `BuyBtn.enabled` true and `RentBtn.enabled` false (L1 is a sale); after `select(1, true)` the flags flip; with `g.state.cash = 100` plus `g.changed.emit()` both are false. `test_ok_button`: `c.on_ok()` with L1 selected sends `buy_car`; with L2 selected sends `rent_car`; with an empty board sends nothing. Free `c` at the end of each test.'''],
  accept=["`sh tools/godot/gtest.sh test_shop_actions` last line is `GDTEST OK`.", "`sh tools/godot/gtest.sh test_shop_channel` last line is `GDTEST OK`.", shot("shop") + " The BUY and RENT buttons must now be visible along the bottom of the right half."]),

 # ------------------------------------------------------------------------------------------------ NEWS channel
 dict(id="GDU14", title="Channel NEWS: The Daily Sprocket pages", needs=["GDU12", "GDU02", "GDU31", FMT],
  files=["godot/tv/news_channel.gd", "godot/tv/news_channel.tscn", "godot/tests/shots/news_shot.tscn", "godot/tests/test_news_channel.gd"],
  goal="The NEWS channel (port of src/ui/scenes/news.js): the front page of The Daily Sprocket (masthead, dateline, headline, today's events), the month-end bills page when there is one, and a BACK ISSUES page listing recent headlines. OK / the NEXT button turn the page.",
  read=[PLAN, TESTS, CB, BTN, UTXT, THEME, FAKE, CHAN, "src/ui/scenes/news.js (read it all: pages 1 and 2, MAX_EVENTS 6 there; this port shows 5 to fit the small screen, monthReport fields)", "godot/core/format.gd (GDF07: `CoreFormat.money`, `CoreFormat.date_text(day)`)"],
  steps=[
   ch_tscn("news"),
   r'''`godot/tv/news_channel.gd`: `class_name NewsChannel`, `extends ChannelBase`. `_init`: `super()`; `title = "NEWS"`. Vars `page: int = 0`. Static helpers (pure, they take the state): `static func page_kinds(st: Dictionary) -> Array[String]`: `["front", "month", "back"]` when `st.today.monthReport != null` else `["front", "back"]`. `static func front(st: Dictionary) -> Dictionary`: `{"dateline": "DAY %d  -  %s" % [day, CoreFormat.date_text(day)], "headline": UiText.wrap(str(st.today.headline).to_upper(), 36, 3), "events": Array}` where `day = int(st.day)` and `events` is the first 5 of `st.today.events`, each `UiText.ellipsize(str(e), 48)`, and a 6th entry `"...and more"` when there were more than 5. (Use `int(st.get("day", 1))`; the dateline uses `date_text` only when day is 1..365, else "YEAR END".) `static func month_lines(report: Dictionary) -> Array[String]`: `"Rent " + CoreFormat.money(report.rent)`, `"Running costs " + CoreFormat.money(report.running)`, `"Garage lease " + CoreFormat.money(report.lease)`, `"TOTAL " + CoreFormat.money(report.total)`, `"Cash now " + CoreFormat.money(report.cashAfter)`, followed by one `"Fault: " + f` (ellipsized to 40) per entry of `report.newFaults` (at most 4).''',
   r'''Navigation: `func kinds() -> Array[String]: return NewsChannel.page_kinds(state())`. `func kind() -> String: return kinds()[clampi(page, 0, kinds().size() - 1)]`. `func next_page() -> void: page = (page + 1) % kinds().size(); queue_redraw()`. `func on_ok() -> void: next_page()`. `func on_back() -> bool`: if `page > 0` { `page = 0`; `queue_redraw()`; return true }; return false. `func _on_enter() -> void: page = 0`. `func refresh() -> void`: `page = mini(page, kinds().size() - 1)`; `queue_redraw()` (a new day returns to the front page: when `int(state().day)` differs from `_last_day` set `page = 0` and update `_last_day`; `_on_enter` also sets `_last_day` to the current day). In `_ready()` create `NextBtn` (a `UiButton`, `text = "NEXT"`, `Vector2(552, 368)`, size `Vector2(80, 72)`) whose `activated` calls `next_page`.''',
   r'''`_paint()`: paper sheet `UiTheme.draw_box(self, Rect2(16, 48, 608, 310), UiTheme.color("paper"), UiTheme.color("ink"), 4, true)`. Masthead (all pages) "THE DAILY SPROCKET" centred at y 58 (role "h2", colour "ink", width 640). Page "front": a 3 px ink rule at y 94; dateline (role "caption", colour "darkgrey", centred) at y 100; headline lines at x 32, y 124 + k * 22 (role "h3", colour "ink"); a 2 px ink rule at y 192; "TODAY IN WEBB'S WHEELS:" (role "h3") at y 198; then the events one per line from y 220, pitch 20, each prefixed "* " (role "caption", colour "ink"; a line containing "GOLD NUMBER PLATE" is drawn in "gold"). Page "month": heading "MONTH END: " + `str(report.monthName).to_upper()` (role "h3") at y 100 then the `month_lines` at y 132 + k * 28 (role "caption"; lines starting with "Fault:" in colour "bad"). Page "back": heading "BACK ISSUES" at y 100 and the first 8 entries of `state().headlines`, each `UiText.ellipsize(h, 52)` at y 130 + k * 26 (role "caption", colour "ink"); nothing to show -> "No back issues yet.". At the bottom of the paper, right-aligned, a page marker `"%d/%d" % [page + 1, kinds().size()]` (role "caption", colour "midgrey") at y 330.''',
   shot_scene("news"),
   r'''`godot/tests/test_news_channel.gd`: pure helpers first (state from `TestFakeGame.sample_state()`): `test_page_kinds`: `page_kinds(st) == ["front", "back"]`; with `st.today.monthReport = {...}` it is `["front", "month", "back"]`. `test_front`: `front(st).dateline == "DAY 12  -  12 January"`; `front(st).headline == ["LOCAL VICAR BUYS ROUND OF TEA"]`; `front(st).events == ["Bought nothing. Lovely.", "Dave found a spanner."]`; with 8 events in `st.today.events` the events list has 6 entries and the last is `"...and more"`; a 100-character event is cut to 48 characters ending in "..."; `day = 400` gives a dateline ending in `YEAR END`. `test_month_lines`: report `{"monthName": "January", "rent": 240, "running": 300, "lease": 400, "total": 940, "cashAfter": 5000, "newFaults": ["Flat tyre"]}`: the lines equal `["Rent " + CoreFormat.money(240), "Running costs " + CoreFormat.money(300), "Garage lease " + CoreFormat.money(400), "TOTAL " + CoreFormat.money(940), "Cash now " + CoreFormat.money(5000), "Fault: Flat tyre"]`. Scene tests (instantiate `res://tv/news_channel.tscn`, add to the tree, `enter(g)`): `test_pages`: `kind() == "front"`; `on_ok()`: "back" (no month report) ; `on_ok()`: wraps to "front"; with a month report in `g.state.today.monthReport` and `g.changed.emit()`: the cycle is front, month, back, front; `on_back()` on page 1 returns true and resets `page` to 0; `on_back()` on page 0 returns false. `test_next_button`: tapping `NextBtn` (press+release inside via `handle_event`) advances the page; `NextBtn.size.y >= 72.0`. `test_new_day_resets_page`: go to page 1; set `g.state.day = 13` and emit `changed`: `page == 0`. Free nodes after each test.'''],
  accept=["`sh tools/godot/gtest.sh test_news_channel` last line is `GDTEST OK`.", shot("news")]),

 # ------------------------------------------------------------------------------------------------ ADVERTS channel
 dict(id="GDU15", title="Channel ADVERTS: media list and run advert", needs=["GDU12", "GDU18", "GDU02", "GDU31", DATA, FMT],
  files=["godot/tv/adverts_math.gd", "godot/tv/adverts_channel.gd", "godot/tv/adverts_channel.tscn", "godot/tests/shots/adverts_shot.tscn", "godot/tests/test_adverts_channel.gd"],
  goal="The ADVERTS channel (port of src/ui/scenes/adverts.js): Mark's seven advertising media in a list with cost, PAYS pips and RISK %, a detail panel with the blurb and numbers, a BUZZ meter and a RUN ADVERT button that calls `game.act('advertise')` and shows the funny result.",
  read=[PLAN, TESTS, CB, LSTW, BTN, UTXT, THEME, FAKE, CHAN, "src/ui/scenes/adverts.js (read it all: expectedBuzz, flopChance, bestBuzz, rows, detail)", "src/sim/adsim.js (the result: `{ok, msg, outcome: {id, buzz, rep, mediaId}}`)", "godot/autoload/data.gd (GDF03: `Data.adverts()`, `Data.advert_by_id(id)`)"],
  steps=[
   r'''`godot/tv/adverts_math.gd`: `class_name AdvertsMath`, `extends RefCounted`, static. `static func expected_buzz(medium: Dictionary) -> float`: sum over `medium.outcomes` of `float(o.w) * float(o.buzz)`, divided by 100.0. `static func flop_chance(medium: Dictionary) -> int`: sum of `int(o.w)` over outcomes with `o.buzz <= 5`. `static func best_buzz(medium: Dictionary) -> int`: the largest `o.buzz` (0 if none). `static func pays(medium: Dictionary) -> int: return int(floor(expected_buzz(medium) / 10.0 + 0.5))` (JS Math.round of eb/10). `static func result_lines(res: Dictionary) -> Array[String]`: for a successful act result: `UiText.wrap(str(res.msg), 40, 5)` followed by `"Buzz " + sign + str(abs(buzz))` and `"Reputation " + sign + str(abs(rep))` lines for the values in `res.outcome` that are not zero (sign `+` or `-`); if both are zero add `"Nothing much changed."`.''',
   ch_tscn("adverts"),
   r'''`godot/tv/adverts_channel.gd`: `class_name AdvertsChannel`, `extends ChannelBase`. `_init`: `super()`; `title = "ADVERTS"`. Vars `result: Array[String] = []` (non-empty = the result panel is showing). `_ready()`: `List` (`UiList` at `Rect2(8, 76, 300, 292)`, `row_h = 72`, `row_painter = _paint_row`, `set_count(Data.adverts().size())`, `select(0)`; `row_tapped` -> `queue_redraw()`), `RunBtn` (`UiButton`, kind "primary", `Vector2(316, 376)`, size `Vector2(316, 72)`, `activated` and `blocked` -> `_run`), `OkBtn` (`UiButton`, `text = "OK"`, `Vector2(316, 376)`, size `Vector2(316, 72)`, `visible = false`, `activated` -> `dismiss`). `func medium() -> Dictionary`: `Data.adverts()[List.selected]` for a valid selection else `{}`. `func refresh() -> void`: update the button text and enabled state: `RunBtn.text = "RUN ADVERT " + CoreFormat.money(medium().cost)`; `RunBtn.enabled = float(state().get("cash", 0)) >= float(medium().cost)`; `queue_redraw()`.''',
   r'''Action: `func _run() -> void`: `var m := medium()`; if `m.is_empty()` return; if `float(state().cash) < float(m.cost)`: `toast("Not enough money")` and return; `var res: Dictionary = game.act("advertise", {"media_id": m.id})`; if `res.get("ok", false)`: `result = AdvertsMath.result_lines(res)`; `RunBtn.visible = false`; `OkBtn.visible = true`; `queue_redraw()`. (A failed act is already toasted by Game.) `func dismiss() -> void`: `result = []`, `RunBtn.visible = true`, `OkBtn.visible = false`, `queue_redraw()`. `func on_ok() -> void: if result.is_empty(): _run() else: dismiss()`. `func on_back() -> bool: if not result.is_empty(): dismiss(); return true`; `return false`.''',
   r'''Drawing. Row painter `func _paint_row(list: Control, i: int, r: Rect2, sel: bool) -> void`: `var m: Dictionary = Data.adverts()[i]`; box paper/ink as in the SHOP rows; medium name `UiText.ellipsize(m.name, 17)` (role "caption", ink) at `r.position + Vector2(12, 4)`; cost right-aligned (role "caption", colour "darkgrey") at the right edge; line 2 at y + 34: `"PAYS " + UiText.pips(AdvertsMath.pays(m))` (role "caption", colour "good") on the left and `"RISK %d%%" % AdvertsMath.flop_chance(m)` right-aligned (colour "bad"). Selected row: 4 px "lamp" outline. `_paint()`: BUZZ meter at the top: `"BUZZ %d" % int(round(float(state().get("buzz", 0))))` (role "h3", colour "phosphor") at (8, 50) and a bar `UiTheme.draw_bar(self, Rect2(160, 50, 300, 16), buzz / 100.0, UiTheme.color("good"))`. Detail panel `UiTheme.draw_box(self, Rect2(316, 76, 316, 292), paper, ink, 4, false)`: when `result` is empty: name (role "h3", ink) `UiText.ellipsize(m.name.to_upper(), 18)` at (328, 88); blurb `UiText.wrap(m.blurb, 29, 5)` lines (role "caption", ink) from y 116, pitch 22; then four lines (role "caption") at y 236, 260, 284, 308: `"Cost " + CoreFormat.money(m.cost)`, `"Typical buzz +%d" % int(round(AdvertsMath.expected_buzz(m)))`, `"Chance of a flop %d%%" % AdvertsMath.flop_chance(m)`, `"Best case +%d buzz" % AdvertsMath.best_buzz(m)`. When `result` is not empty: heading "THE RESULT" (role "h3") and the lines at y 116 + k * 26 (role "caption", ink; lines starting with "Buzz +" in "good", "-" ones in "bad").''',
   shot_scene("adverts"),
   r'''`godot/tests/test_adverts_channel.gd`: `test_math`: `var med := {"outcomes": [{"w": 30, "buzz": 0, "rep": 0}, {"w": 60, "buzz": 8, "rep": 0}, {"w": 10, "buzz": 20, "rep": 0}]}`: `expected_buzz(med)` near 6.8 (eps 1e-9); `flop_chance(med) == 30`; `best_buzz(med) == 20`; `pays(med) == 1` (0.68 rounds to 1); `best_buzz({"outcomes": []}) == 0`. A medium with outcomes buzz 5 (w 10) and buzz 6 (w 90) has `flop_chance == 10`. `test_real_data`: for the paper medium `Data.advert_by_id("paper")`: `flop_chance` >= 0 and `pays` between 0 and 10; the sum of outcome weights is 100 for every medium in `Data.adverts()` (via `flop_chance` is not needed: sum `w` directly). `test_result_lines`: `result_lines({"msg": "It worked.", "outcome": {"buzz": 8, "rep": 0}})` equals `["It worked.", "Buzz +8"]`; `{"buzz": 0, "rep": -2}` gives `[..., "Reputation -2"]`; both 0 gives a last line `"Nothing much changed."`. Scene tests (instantiate `res://tv/adverts_channel.tscn`, add to the tree, `enter(TestFakeGame)`): `test_enter`: `List.count == Data.adverts().size()` (7); `List.selected == 0`; `RunBtn.text == "RUN ADVERT " + CoreFormat.money(medium().cost)`; `RunBtn.enabled` true; `RunBtn.size.y >= 72.0`. `test_run`: tap `RunBtn`: `g.acts == [{"action": "advertise", "params": {"media_id": <first medium id>}}]`; `result` is non-empty and `OkBtn.visible` and not `RunBtn.visible`; `on_back()` returns true and the result is gone; a second `on_back()` returns false. `test_poor`: `g.state.cash = 1` + `g.changed.emit()`: `RunBtn.enabled` false; tapping it sends NO act and `g.toasts == ["Not enough money"]`. `test_ok_key`: `on_ok()` with no result runs the advert; `on_ok()` with a result dismisses. `test_failed_act`: `g.next_result = {"ok": false, "msg": "Nope"}`; tap `RunBtn`: `result` stays empty and `g.toasts == ["Nope"]`. Free after each test.'''],
  accept=["`sh tools/godot/gtest.sh test_adverts_channel` last line is `GDTEST OK`.", shot("adverts")]),

 # ------------------------------------------------------------------------------------------------ LEDGER channel
 dict(id="GDU16", title="Channel LEDGER: books, plates and sales chart", needs=["GDU12", "GDU29", "GDU31", DATA, FMT],
  files=["godot/tv/ledger_math.gd", "godot/tv/ledger_channel.gd", "godot/tv/ledger_channel.tscn", "godot/tests/shots/ledger_shot.tscn", "godot/tests/test_ledger_channel.gd"],
  goal="The LEDGER channel (port of the ledger tab of src/ui/scenes/ledger.js): the books (cash, net worth, stable value, expected next bills, reputation, buzz, stats), progress towards the four Gold Number Plates and the small sales chart. DISPLAY only: the figures are computed here from `state` + `Data` by a small pure class `LedgerMath` (copies of the JS formulas; the real rules stay in the sim).",
  read=[PLAN, TESTS, CB, UTXT, THEME, FAKE, CHAN, "src/ui/scenes/ledger.js (read drawLedger, plateProgress, expectedBills, stableValue)", "src/sim/carstats.js (marketValue, valueFactor, runningCost, maintMult) and src/sim/endgame.js (PLATE_INFO, netWorth)", "godot/ui/sales_chart.gd and cash_history.gd (GDU29)", "godot/core/format.gd (GDF07)"],
  steps=[
   r'''`godot/tv/ledger_math.gd`: `class_name LedgerMath`, `extends RefCounted`, static. `const PLATE_KEYS: Array[String] = ["fatcat", "stable", "household", "hammer"]`, `const PLATE_NAMES := {"fatcat": "Fat Cat", "stable": "Stable Boy", "household": "Household Name", "hammer": "Hammer Time"}`, `const LEASE := 400`. `static func value_factor(condition: float) -> float: return 0.5 + 0.05 * condition`. `static func maint_mult(condition: float) -> float: return 1.0 + (10.0 - condition) * 0.08`. `static func market_value(st: Dictionary, model: Dictionary, car: Dictionary) -> int: return int(floor(float(model.basePrice) * value_factor(float(car.condition)) * float(st.market.priceMult) + 0.5))`. `static func running_cost(model: Dictionary, car: Dictionary) -> int: return int(floor(float(model.maintenance) * (60.0 + float(model.basePrice) * 0.0025) * maint_mult(float(car.condition)) + 0.5))`. `static func stable_value(st: Dictionary, models: Dictionary) -> int`: sum of `market_value` for cars with `owned == true` whose `modelId` is in `models` (unknown models count 0). `static func net_worth(st, models) -> int: return int(floor(float(st.cash) + 0.5)) + stable_value(st, models)`. `static func expected_bills(st, models) -> int`: `LEASE` + `running_cost` of each owned car with a known model + `int(car.rentMonthly)` of each rented car (`owned == false`). `static func owned_count(st) -> int`.''',
   r'''`static func plate_progress(st: Dictionary, key: String, models: Dictionary) -> String`: `"WON"` when `st.plates.get(key, false) == true`; otherwise `fatcat`: `CoreFormat.money(net_worth(st, models)) + "/" + CoreFormat.money(100000)`; `stable`: `"%d/6 cars" % owned_count(st)`; `household`: `"%d/85" % int(st.reputation)`; `hammer`: `"best " + CoreFormat.money(st.stats.bestAuctionSale) + "/" + CoreFormat.money(100000)`. `static func stat_lines(st: Dictionary) -> Array[String]`: `"Jobs done %d / failed %d"`, `"Adverts run %d"`, `"Cars bought %d / sold %d"`, `"Best sale " + CoreFormat.money(bestAuctionSale) + "  Faults %d"` from `st.stats`.''',
   ch_tscn("ledger"),
   r'''`godot/tv/ledger_channel.gd`: `class_name LedgerChannel`, `extends ChannelBase`. `_init`: `super()`; `title = "LEDGER"`. `_ready()` creates `Chart` (`UiSalesChart`, `position = Vector2(336, 256)`, `size = Vector2(296, 112)`). `func refresh() -> void`: `Chart.set_values(UiCashHistory.values(14))`; `queue_redraw()`. (`UiCashHistory` is fed by the HUD; this channel only reads it. If it holds fewer than 2 points, record the current one: `UiCashHistory.record(int(state().get("day", 1)), float(state().get("cash", 0)))` first.) `func _paint()` (use `var st := state()`, `var models := ChannelBase.models_by_id()`): book panel `UiTheme.draw_box(self, Rect2(8, 48, 320, 320), paper, ink, 4, false)`; heading "THE BOOKS" (role "h3", ink) at (24, 56); six rows at x 24, y = 84 + k * 26 (role "caption", colour "ink"): `"Cash " + CoreFormat.money(st.cash)`, `"Net worth " + CoreFormat.money(LedgerMath.net_worth(st, models))`, `"Stable value " + CoreFormat.money(LedgerMath.stable_value(st, models))`, `"Next bills " + CoreFormat.money(LedgerMath.expected_bills(st, models))`, `"Reputation %d/100" % int(st.reputation)`, `"Buzz %d" % int(st.buzz)`; "STATS" (role "h3") at (24, 248) and the four `stat_lines` at y = 272 + k * 22 (role "caption", colour "darkgrey").''',
   r'''Plates panel in `_paint()`: `UiTheme.draw_box(self, Rect2(336, 48, 296, 204), paper, ink, 4, false)`; heading "GOLD NUMBER PLATES" (role "caption", colour "woodDark") at (348, 52). For `k` in 0..3 with `key = LedgerMath.PLATE_KEYS[k]` and `y = 78 + k * 42`: the plate name `LedgerMath.PLATE_NAMES[key]` (role "caption"; colour "gold" when won else "ink") at (348, y), `"WON"` right-aligned at the panel's right edge (only when won, colour "gold"), and the progress string `LedgerMath.plate_progress(st, key, models)` (role "caption", colour "darkgrey", ellipsized to 27) at (348, y + 20).''',
   shot_scene("ledger"),
   r'''`godot/tests/test_ledger_channel.gd`: `test_math` with an explicit tiny model table `models = {"m": {"basePrice": 4000, "maintenance": 2}}` and a state `st = {"cash": 1000, "market": {"priceMult": 1}, "reputation": 60, "plates": {"fatcat": false, "stable": false, "household": false, "hammer": true}, "stats": {"jobsDone": 2, "jobsFailed": 1, "adsRun": 3, "carsBought": 1, "carsSold": 0, "bestAuctionSale": 5000, "faults": 1}, "cars": [{"modelId": "m", "owned": true, "condition": 10.0, "rentMonthly": 0}, {"modelId": "m", "owned": false, "condition": 5.0, "rentMonthly": 200}, {"modelId": "unknown", "owned": true, "condition": 10.0, "rentMonthly": 0}]}`: `value_factor(10.0)` near 1.0; `maint_mult(10.0)` near 1.0; `market_value(st, models.m, st.cars[0]) == 4000`; `running_cost(models.m, st.cars[0]) == 140` (2 * (60 + 10) * 1); `stable_value(st, models) == 4000` (the unknown model and the rental count 0); `net_worth(st, models) == 5000`; `expected_bills(st, models) == 740` (400 + 140 + 200); `owned_count(st) == 2`. `test_plate_progress`: `"stable"` -> `"2/6 cars"`; `"household"` -> `"60/85"`; `"fatcat"` -> `CoreFormat.money(5000) + "/" + CoreFormat.money(100000)`; `"hammer"` -> `"WON"`; with `plates.hammer = false`: `"best " + CoreFormat.money(5000) + "/" + CoreFormat.money(100000)`. `test_stat_lines`: the four lines `["Jobs done 2 / failed 1", "Adverts run 3", "Cars bought 1 / sold 0", "Best sale " + CoreFormat.money(5000) + "  Faults 1"]`. `test_sample_state_with_real_data`: `LedgerMath.net_worth(TestFakeGame.sample_state(), ChannelBase.models_by_id())` equals `12345 + market_value` of the two sample cars (compute both with `LedgerMath.market_value` and `ChannelBase.model_of`) and is greater than 12345. Scene tests (instantiate `res://tv/ledger_channel.tscn`, add to the tree, `UiCashHistory.reset()`, `enter(TestFakeGame)`): `test_enter`: `title == "LEDGER"`; `Chart` exists, `Chart.values.size() >= 1`; after `UiCashHistory.record(13, 20000.0)` and `g.changed.emit()` the chart has 2 values. Reset the history at the end of each scene test and free the node.'''],
  accept=["`sh tools/godot/gtest.sh test_ledger_channel` last line is `GDTEST OK`.", shot("ledger")],
  oos=["The workshop tab and BUY SLOT (GDU24)."]),

 dict(id="GDU24", title="Channel LEDGER: workshop tab and buy slot", needs=["GDU16", "GDU02"],
  files=["godot/tv/ledger_channel.gd", "godot/tests/shots/ledger_workshop_shot.tscn", "godot/tests/test_ledger_workshop.gd"],
  goal="Add the WORKSHOP tab to the LEDGER channel (the garage board: bays in use and BUY EXTRA SLOT, port of drawWorkshop in ledger.js). A TAB button swaps the books for the workshop; BUY SLOT calls `game.act('buy_slot')`.",
  read=[PLAN, TESTS, CB, BTN, FAKE, CHAN, "godot/tv/ledger_channel.gd (GDU16)", "src/ui/scenes/ledger.js (drawWorkshop, BAYS, MAX_SLOTS 8, SLOT_COST 3000) and src/sim/actions.js buySlot"],
  steps=[
   r'''Edit `godot/tv/ledger_channel.gd`. Add consts `MAX_SLOTS := 8`, `SLOT_COST := 3000`; var `tab: String = "books"`; `static func slot_refusal(st: Dictionary) -> String`: `int(st.garageSlots) >= 8` -> `"Garage is full-size already"`; `float(st.cash) < 3000.0` -> `"Not enough money"`; else `""`. `func set_tab(t: String) -> void`: `tab = "workshop" if t == "workshop" else "books"`; update visibility: `Chart.visible = (tab == "books")`, `BuySlotBtn.visible = (tab == "workshop")`; `TabBtn.text = "WORKSHOP" if tab == "books" else "BOOKS"`; `queue_redraw()`.''',
   r'''In `_ready()` add `TabBtn` (`UiButton`, `Vector2(8, 376)`, size `Vector2(200, 72)`, `text = "WORKSHOP"`, `activated` -> `func(): set_tab("workshop" if tab == "books" else "books")`) and `BuySlotBtn` (`UiButton`, kind "primary", `Vector2(232, 376)`, size `Vector2(400, 72)`, `text` set in `refresh()` to `"BUY SLOT " + CoreFormat.money(SLOT_COST)`, `visible = false`, `activated` and `blocked` -> `_buy_slot`). `func _buy_slot() -> void`: `var why := LedgerChannel.slot_refusal(state())`; if `why != ""`: `toast(why)`, return; `var res: Dictionary = game.act("buy_slot")`; on `ok` `toast(str(res.msg))`. `refresh()` also sets `BuySlotBtn.enabled = LedgerChannel.slot_refusal(state()) == ""`. `func on_ok() -> void: if tab == "workshop": _buy_slot()`. `func on_back() -> bool: if tab == "workshop": set_tab("books"); return true`; `return false`. `_on_enter` sets the tab to "books".''',
   r'''`_paint()`: in the "workshop" tab skip the books/plates/chart drawing and draw instead: board `UiTheme.draw_box(self, Rect2(8, 48, 624, 316), paper, ink, 4, false)`; heading "WORKSHOP BOARD" (role "h3") at (24, 58); `"Garage slots %d/%d" % [slots, 8]` right-aligned (role "caption") at y 58; the label "Garage bays" (role "caption", colour "darkgrey") at (24, 120); the bays: for `i` in `0..slots-1`: `Rect2(24 + i * 74, 150, 68, 80)` filled with `good` when `i < cars.size()` else `cream` (via `draw_box`, 4 px ink border, no shadow), number `i + 1` centred (role "h3", colour white or darkgrey); below, at y 250, a caption line `"%d of %d bays in use" % [cars.size(), slots]` (role "caption", ink). The books drawing from GDU16 only runs in the "books" tab.''',
   r'''`godot/tests/shots/ledger_workshop_shot.tscn`: the same shape as `ledger_shot.tscn` (GDU16) with `metadata/channel = "res://tv/ledger_channel.tscn"` and one more line `metadata/calls = [["set_tab", ["workshop"]]]`.''',
   r'''`godot/tests/test_ledger_workshop.gd` (scene `res://tv/ledger_channel.tscn` entered with a `TestFakeGame` `g`; helper `_tap(btn)` as in the SHOP card): `test_refusal`: `slot_refusal(sample)` is `""` (cash 12345, 3 slots); `garageSlots = 8` -> `"Garage is full-size already"` (even with cash 0); `cash = 2999` -> `"Not enough money"`. `test_tabs`: `tab == "books"`, `Chart.visible`, not `BuySlotBtn.visible`; `_tap(TabBtn)`: `tab == "workshop"`, `TabBtn.text == "BOOKS"`, `BuySlotBtn.visible`, not `Chart.visible`; `_tap(TabBtn)` again returns to books. `test_buy`: in the workshop tab `_tap(BuySlotBtn)`: `g.acts == [{"action": "buy_slot", "params": {}}]` and the success text is toasted. `test_refused_buy`: `g.state.cash = 10` + `g.changed.emit()`: `BuySlotBtn.enabled` false; `_tap(BuySlotBtn)` sends no act and `g.toasts == ["Not enough money"]`. `test_back`: `on_back()` in the workshop returns true and goes to books; in books returns false. `test_button_sizes`: `TabBtn.size.y >= 72.0` and `BuySlotBtn.size.y >= 72.0`. Also re-run in the acceptance: the GDU16 test file must still pass.'''],
  accept=["`sh tools/godot/gtest.sh test_ledger_workshop` last line is `GDTEST OK`.", "`sh tools/godot/gtest.sh test_ledger_channel` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh tests/shots/ledger_workshop_shot.tscn /tmp/ledger_workshop.png 8`, LOOK at /tmp/ledger_workshop.png and describe it (expected: a paper board with WORKSHOP BOARD, three bays (two filled green, one cream), a big BUY SLOT button with the price, a BOOKS tab button)."]),

 # ------------------------------------------------------------------------------------------------ BOOKINGS channel
 dict(id="GDU17", title="Channel BOOKINGS: requests, cars and needs", needs=["GDU12", "GDU18", "GDU02", "GDU31", DATA, FMT],
  files=["godot/tv/bookings_math.gd", "godot/tv/bookings_channel.gd", "godot/tv/bookings_channel.tscn", "godot/tests/shots/bookings_shot.tscn", "godot/tests/test_bookings_channel.gd"],
  goal="The BOOKINGS channel, display half (port of src/ui/scenes/bookings.js): the hire diary. A scrolling list of customer requests, a detail panel with the fee and what the job needs (Style / Reliability / Condition, with OK or NO for the chosen car), and a strip of the player's own cars (3 per page, with prev / next) greyed out with the reason when a car cannot take the job. Accepting comes in GDU25.",
  read=[PLAN, TESTS, CB, LSTW, BTN, UTXT, THEME, FAKE, CHAN, "src/ui/scenes/bookings.js (read it all: carBlock, canAccept, ownedCars, detail panel, strip)", "src/sim/carstats.js (effD, effR, isAvailable)", "godot/autoload/data.gd (GDF03)"],
  steps=[
   r'''`godot/tv/bookings_math.gd`: `class_name BookingsMath`, `extends RefCounted`, static. `static func eff_d(model: Dictionary, car: Dictionary) -> float: return float(model.desirability) * (0.40 + 0.06 * float(car.condition))`. `static func eff_r(model: Dictionary, car: Dictionary) -> float: return float(model.reliability) * (0.30 + 0.07 * float(car.condition))`. `static func block_reason(st: Dictionary, car: Dictionary, req: Dictionary, model: Dictionary) -> String` (`""` = fine), in this order: `car.fault != null` -> `"FAULT"`; `int(car.impoundedUntil) > int(st.day)` -> `"IMPOUNDED"`; `model.is_empty()` -> `"FAULT"`; then only when `req` is not empty: `eff_d(model, car) < float(req.minDesirability)` -> `"TOO PLAIN"`; `eff_r(...) < float(req.minReliability)` -> `"TOO FLAKY"`; `float(car.condition) < float(req.minCondition)` -> `"TOO SCRUFFY"`. `static func owned_cars(st: Dictionary, models: Dictionary) -> Array`: the cars with `owned == true` whose `modelId` is a key of `models` (order kept). `static func days_left(st: Dictionary, req: Dictionary) -> int: return int(req.expiresDay) - int(st.day)`.''',
   ch_tscn("bookings"),
   r'''`godot/tv/bookings_channel.gd`: `class_name BookingsChannel`, `extends ChannelBase`. `_init`: `super()`; `title = "BOOKINGS"`. Vars `sel_req: String = ""`, `sel_car: String = ""`, `car_page: int = 0`. Consts `PER_PAGE := 3`. `_ready()` creates `Requests` (`UiList` at `Rect2(8, 48, 300, 248)`, `row_h = 72`, `row_painter = _paint_req_row`, `row_tapped` -> `_on_req`), `PrevBtn` (`UiButton`, text "<", `Rect2(8, 300, 72, 72)`), `NextBtn` (text ">", `Rect2(560, 300, 72, 72)`), and three car slot buttons `Car0`, `Car1`, `Car2` (`UiButton`, kind "card", `role = "caption"`, rects `Rect2(88, 300, 150, 72)`, `Rect2(244, 300, 150, 72)`, `Rect2(400, 300, 150, 72)`). `PrevBtn`/`NextBtn` `activated` call `page_cars(-1)` / `page_cars(1)`; every car slot's `activated` AND `blocked` call `_on_car(slot_index)`. `func requests() -> Array: return state().get("requests", [])`. `func cars() -> Array: return BookingsMath.owned_cars(state(), ChannelBase.models_by_id())`. `func req_by_id(id: String) -> Dictionary` and `func car_by_id(id: String) -> Dictionary` (linear scans, `{}` when unknown). `func _on_req(i: int) -> void: sel_req = str(requests()[i].id); refresh()`. `func page_cars(d: int) -> void`: `var pages := maxi(1, int(ceil(cars().size() / 3.0)))`; `car_page = clampi(car_page + d, 0, pages - 1)`; `refresh()`.''',
   r'''`func _on_car(slot: int) -> void`: `var idx := car_page * PER_PAGE + slot`; if `idx >= cars().size()` return; `var car: Dictionary = cars()[idx]`; `var why := BookingsMath.block_reason(state(), car, req_by_id(sel_req), ChannelBase.model_of(str(car.modelId)))`; if `why != ""`: `toast("That car is not fit for this booking: " + why.to_lower())` and return; `sel_car = str(car.id)`; `refresh()`. `func refresh() -> void`: drop selections whose id no longer exists (`sel_req`, `sel_car` become `""`); `Requests.set_count(requests().size())`; keep `Requests.selected` in step with `sel_req` (select the row whose id equals `sel_req`, else -1); update the three car slots: for slot `s` with `idx = car_page * 3 + s`: when `idx >= cars().size()` -> `text = ""`, `visible = false`; else visible, `text = UiText.ellipsize(model.name, 12) + "\n" + (reason if reason != "" else "Cond " + CoreFormat.one_dp(car.condition))`, `enabled = reason == ""`, `hot = (car.id == sel_car)`; `PrevBtn.enabled = car_page > 0`; `NextBtn.enabled = (car_page + 1) * 3 < cars().size()`; `queue_redraw()`. (`reason` = `block_reason(state(), car, req_by_id(sel_req), model)`.)''',
   r'''Row painter `func _paint_req_row(list: Control, i: int, r: Rect2, sel: bool) -> void`: `var q: Dictionary = requests()[i]`; box paper/ink (as the SHOP rows); line 1 `UiText.ellipsize(ChannelBase.job_name(q.jobTypeId).to_upper(), 14)` (role "h3", ink) at `r.position + Vector2(12, 8)`; days left right-aligned on line 1 (role "caption", colour "bad" when `days_left <= 1` else "darkgrey"): `"%dd left" % BookingsMath.days_left(state(), q)`; line 2 at y + 38: customer `UiText.ellipsize(q.customer, 16)` (role "caption", ink) on the left and the fee `CoreFormat.money(q.fee)` right-aligned (role "caption", colour "good"); selected -> 4 px "lamp" outline. `_paint()`: detail panel `UiTheme.draw_box(self, Rect2(316, 48, 316, 248), paper, ink, 4, false)`. No request chosen: `UiText.wrap("Pick a booking on the left, then pick a car for the job.", 27, 4)` (role "caption", ink) from (328, 60), pitch 26; an empty diary (`requests()` empty): `UiText.wrap("No bookings. The phone is suspiciously quiet. Try advertising.", 27, 4)`. Chosen request: job name (role "h3") at (328, 56); the blurb `UiText.wrap(q.blurb, 29, 4)` (role "caption") from y 80, pitch 22; `"Fee " + CoreFormat.money(q.fee)` (role "caption", colour "good") at y 176; then three needs rows at y 202, 226, 250 (role "caption") with exactly these labels: `"Style %d"`, `"Reliab %d"`, `"Cond %d"` (values `minDesirability`, `minReliability`, `minCondition`); when a car is chosen add at x 470 `"OK"`/`"NO"` (role "h3", "good" / "bad") and at x 530 the car's figure (`eff_d`, `eff_r`, `condition`, one decimal).''',
   shot_scene("bookings"),
   r'''`godot/tests/test_bookings_channel.gd`: `test_math` with `model = {"desirability": 5, "reliability": 4}` and `car = {"condition": 10.0, "fault": null, "impoundedUntil": 0}`: `eff_d(model, car)` near 5.0 (0.40 + 0.06 * 10 = 1.0); `eff_r(model, car)` near 4.0; with condition 0: `eff_d` near 2.0, `eff_r` near 1.2. `test_block_reason` (state `{"day": 12}`, `req = {"minDesirability": 3, "minReliability": 3, "minCondition": 6}`): fine car -> `""`; `fault = {"label": "x"}` -> `"FAULT"`; `impoundedUntil = 13` -> `"IMPOUNDED"`; `impoundedUntil = 12` -> `""`; an empty `model` -> `"FAULT"`; `model.desirability = 2` -> `"TOO PLAIN"`; `reliability = 2` with good D -> `"TOO FLAKY"` ; condition 5.0 with strong model -> `"TOO SCRUFFY"`; with an empty `req` a plain-but-working car -> `""`. `test_owned_cars`: sample cars + one rented + one with an unknown model id: only the two sample owned cars remain, in order. `test_days_left`: `days_left({"day": 12}, {"expiresDay": 14}) == 2`. Scene tests (instantiate `res://tv/bookings_channel.tscn`, add to the tree, `enter(TestFakeGame)`): `test_enter`: `Requests.count == 2`; `title == "BOOKINGS"`; `Car0.visible` and `Car1.visible`, not `Car2.visible`; `Car0.size.y >= 72.0`; `PrevBtn.enabled` false; `NextBtn.enabled` false. `test_pick_request`: `Requests.select(0, true)`: `sel_req == "Q1"`. `test_car_strip_reasons`: with Q1 picked, `Car0.text` equals `UiText.ellipsize(ChannelBase.model_of("t1_allergy").name, 12) + "\n" + "TOO PLAIN"`; that is (t1_allergy desirability 1 cannot meet D 3), `Car0.enabled` false; `Car1.text` ends with `"\nFAULT"` (the sample c2 has a fault). `test_pick_car_refused`: tapping `Car0` (press+release inside) leaves `sel_car == ""` and toasts a string containing `"too plain"`. `test_pick_car_ok`: make c1 strong: `g.state.cars[0].modelId = "t3_porshe"` and `condition = 10.0`, `g.changed.emit()`; pick Q1; tap `Car0`: `sel_car == "c1"` and `Car0.hot` true. `test_paging`: append three more owned cars to `g.state.cars` (copies of c1 with ids c3, c4, c5 and modelId "t1_chimp": 5 owned in total, two pages) + `changed`: `NextBtn.enabled` true; `car_page` becomes 1 after tapping `NextBtn`; `Car2.visible` false on page 2 (cars 4 and 5 only... 5 cars: page 2 has 2 cars so Car2 hidden); `PrevBtn.enabled` true. `test_vanished_request`: pick Q1, remove Q1 from `g.state.requests`, `changed`: `sel_req == ""`. Free nodes after each test.'''],
  accept=["`sh tools/godot/gtest.sh test_bookings_channel` last line is `GDTEST OK`.", shot("bookings")],
  oos=["Accepting the job and the result panel (GDU25)."]),

 dict(id="GDU25", title="Channel BOOKINGS: accept job and result panel", needs=["GDU17"],
  files=["godot/tv/bookings_channel.gd", "godot/tests/shots/bookings_result_shot.tscn", "godot/tests/test_bookings_actions.gd"],
  goal="Add ACCEPT JOB to the BOOKINGS channel: it explains every refusal with a toast before acting, calls `game.act('accept_job')`, then shows the job RESULT (type, money, the funny text) on a result panel that OK or BACK dismisses.",
  read=[PLAN, TESTS, CB, BTN, UTXT, FAKE, CHAN, "godot/tv/bookings_channel.gd (GDU17)", "src/ui/scenes/bookings.js `onAccept` (the exact refusal messages and order)", "src/sim/jobresolve.js acceptJob (the result `{ok, msg, outcome: {type, paid, wear, faultLabel}}` where type is success, mishap, breakdown or disaster; `paid` is negative for compensation)", "godot/autoload/game.gd (GDF10: failed actions are toasted by Game itself)"],
  steps=[
   r'''Edit `godot/tv/bookings_channel.gd`. Add `var result: Dictionary = {}` (empty = no result showing). Add `static func accept_refusal(st: Dictionary, req: Dictionary, car: Dictionary, model: Dictionary) -> String` (`""` = fine), in the order of the JS `onAccept`: `car.is_empty()` -> `"Pick a car first"`; the car has a fault or is impounded or the model is empty (`BookingsMath.block_reason` returns `"FAULT"` or `"IMPOUNDED"`) -> `"That car is not fit to go out"`; `req.is_empty()` -> `"Pick a booking first"`; `BookingsMath.eff_d(...) < req.minDesirability` -> `"That car is too plain for this booking"`; `eff_r < req.minReliability` -> `"That car is too flaky for this booking"`; `car.condition < req.minCondition` -> `"That car is too scruffy for this booking"`; else `""`.''',
   r'''Add `AcceptBtn` in `_ready()` (`UiButton`, kind "primary", `Rect2(8, 376, 624, 72)`, `activated` and `blocked` -> `_accept`) and `OkBtn` (`UiButton`, text "OK", the same rect, `visible = false`, `activated` -> `dismiss`). In `refresh()` set `AcceptBtn.text = "ACCEPT JOB " + (CoreFormat.money(req.fee) if a request is chosen else "")` and `AcceptBtn.enabled = accept_refusal(...) == ""`. `func _accept() -> void`: `var req := req_by_id(sel_req)`, `var car := car_by_id(sel_car)`, `var model := ChannelBase.model_of(str(car.get("modelId", "")))`; `var why := BookingsChannel.accept_refusal(state(), req, car, model)`; if `why != ""`: `toast(why)`, return; `var res: Dictionary = game.act("accept_job", {"request_id": req.id, "car_id": car.id})`; if `res.get("ok", false)`: `result = {"text": str(res.get("msg", "")), "type": str(res.get("outcome", {}).get("type", "success")), "paid": int(res.get("outcome", {}).get("paid", 0))}`; `sel_req = ""`; `sel_car = ""`; show the panel (`AcceptBtn.visible = false`, `OkBtn.visible = true`); `queue_redraw()`. `func dismiss() -> void`: `result = {}`; swap the buttons back; `refresh()`. `func on_ok() -> void: if result.is_empty(): _accept() else: dismiss()`. `func on_back() -> bool: if not result.is_empty(): dismiss(); return true`; `return false`.''',
   r'''Result drawing: `static func type_label(t: String) -> String`: `{"success": "JOB DONE", "mishap": "MISHAP", "breakdown": "BREAKDOWN", "disaster": "DISASTER"}.get(t, "JOB DONE")`. `static func paid_text(paid: int) -> String`: `paid > 0` -> `"Paid " + CoreFormat.money(paid)`; `paid < 0` -> `"Compensation " + CoreFormat.money(-paid)`; else `"Paid nothing"`. `static func type_color_name(t: String) -> String`: success "good", mishap "warn", breakdown and disaster "bad". When `result` is not empty `_paint()` draws ONLY the result panel (hide the Requests list and the strip while it shows: `refresh()` sets `Requests.visible`, `PrevBtn.visible`, `NextBtn.visible` to `result.is_empty()`, and a car slot is visible only when `result.is_empty()` and it has a car; `AcceptBtn.visible = result.is_empty()` and `OkBtn.visible = not result.is_empty()`; `_accept` sets `result` and then calls `refresh()` and `queue_redraw()`, and `dismiss()` clears `result` and calls `refresh()`): `UiTheme.draw_box(self, Rect2(8, 48, 624, 316), paper, ink, 4, true)`; the label `type_label` (role "h1", colour `UiTheme.color(type_color_name(type))`, centred, width 640) at y 62; `paid_text` (role "h2", ink, centred) at y 108; the text `UiText.wrap(result.text, 48, 6)` at x 28, y 156, pitch 26 (role "caption", ink).''',
   r'''`godot/tests/shots/bookings_result_shot.tscn`: like `bookings_shot.tscn` (GDU17) plus `metadata/calls = [["_test_show_result", [{"text": "Mrs Pym wept into a very good hankie. The Reliable Robbin swept up to the church as the bells rang.", "type": "success", "paid": 900}]]]`. Add to `bookings_channel.gd` the public helper `func _test_show_result(r: Dictionary) -> void: result = r; show the panel exactly as `_accept` does` (the screenshot uses it).''',
   r'''`godot/tests/test_bookings_actions.gd` (channel from `res://tv/bookings_channel.tscn`, entered with `TestFakeGame` `g`; helper `_tap(btn)`). Make car c1 a strong, healthy car first: in a helper `_strong(g)`: `g.state.cars[0].modelId = "t3_porshe"`, `g.state.cars[0].condition = 10.0`, then `g.changed.emit()`. `test_refusal_order`: pure `accept_refusal` with `req = g.state.requests[0]`: empty car -> `"Pick a car first"`; the faulty sample car c2 -> `"That car is not fit to go out"`; empty req with a good car -> `"Pick a booking first"`; `req.minDesirability = 99` -> `"That car is too plain for this booking"`; `req.minReliability = 99` (with D met) -> `"That car is too flaky for this booking"`; `req.minCondition = 11` (with D and R met) -> `"That car is too scruffy for this booking"`; a good match -> `""`. Use the model from `ChannelBase.model_of`. `test_labels`: `type_label("disaster") == "DISASTER"`, `type_label("zzz") == "JOB DONE"`; `paid_text(900) == "Paid " + CoreFormat.money(900)`; `paid_text(-250) == "Compensation " + CoreFormat.money(250)`; `paid_text(0) == "Paid nothing"`; `type_color_name("mishap") == "warn"`. `test_accept_flow`: `_strong(g)`; pick Q1 (`Requests.select(0, true)`), tap `Car0`, then `AcceptBtn.enabled` is true and its text is `"ACCEPT JOB " + CoreFormat.money(900)`; set `g.next_result = {"ok": true, "msg": "All went well.", "outcome": {"type": "success", "paid": 900, "wear": 0.3, "faultLabel": null}}`; `_tap(AcceptBtn)`: `g.acts == [{"action": "accept_job", "params": {"request_id": "Q1", "car_id": "c1"}}]`; `result.type == "success"`, `result.paid == 900`, `result.text == "All went well."`; `OkBtn.visible`, not `AcceptBtn.visible`, not `Requests.visible`; `sel_req == ""`. `test_dismiss`: `on_back()` returns true and the panel is gone (`result.is_empty()`, `Requests.visible`); `on_back()` again returns false. `test_refused_tap`: nothing chosen: `_tap(AcceptBtn)` (disabled, so `blocked` fires): `g.acts` is empty and `g.toasts == ["Pick a car first"]`. `test_failed_act`: `g.next_result = {"ok": false, "msg": "Expired"}`; accept: `result.is_empty()` and `g.toasts == ["Expired"]`. `test_ok_key`: `on_ok()` accepts when ready and dismisses when a result shows. `test_sizes`: `AcceptBtn.size.y >= 72.0`. Free nodes after each test.'''],
  accept=["`sh tools/godot/gtest.sh test_bookings_actions` last line is `GDTEST OK`.", "`sh tools/godot/gtest.sh test_bookings_channel` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh tests/shots/bookings_result_shot.tscn /tmp/bookings_result.png 8`, LOOK at /tmp/bookings_result.png and describe it (expected: a paper panel with a big green JOB DONE, Paid and the amount, then the wrapped result text, and an OK button along the bottom)."]),
]
